	-- Treasure/rare how-to notes (popup body + row tooltips)
	ACH_NOTE_ROOKERY = "On the floating Sunwing Rookery platform (Falconwing Square): buy Tasty Meat from Farstrider Aerieminder (by the balcony), then drop it next to the Mischievous Chick opposite the chest to get the key. Reward: Sunwing Hatchling pet.",
	ACH_NOTE_SAFEBOX = "Needs 3 hidden Safebox Keys — grab the purple torch next to the chest to reveal them, then pick up the keys nearby.",
	ACH_NOTE_PHOENIX = "Use Gift of the Phoenix, then collect 5 embers from the reborn phoenixes.",
	ACH_NOTE_STONEVAT = "On an elevated platform: pick 10x Bunch of Ripe Grapes nearby and add them to the Vat, then buy a Packet of Instant Yeast from Sheri and add that too.",
	ACH_NOTE_GOURD = "In a small cave (entrance ~27.5, 68.0). Loot Mysterious Red Fluid from the Dangling Jug and Mysterious Purple Fluid from the Hanging Flask, add both to the Durable Vase to make Fizzing Fluid, then open the gourd.",
	ACH_NOTE_SPORECACHE = "Interact with the red Fungal Mallet in Fungara Village for a buff, then use it to ring the Mycelium Gong. The treasure appears next to the gong.",
	ACH_NOTE_CAULDRON = "Nai'theren Grotto (under a bridge just E of Har'mara). Open it with 150x Crystalized Resin Fragment, looted from Flame-Hardened Sap of Teldrassil. The saps are scattered in and along the whole river that runs through this area (from Nai'theren Grotto down past the Shrine of Ages and Vale of Secrets to the Den) - they are NOT on the minimap and respawn, so sweep the river (2-7 fragments each). The fragments are Warbound, so you can farm on any character and pool them via the Warband Bank. Tip: an Inky Black Potion darkens the world so the purple saps stand out. Bug: the saps vanish at exactly 149 fragments - delete 1 to make them reappear.",
	ACH_NOTE_GIFTCYCLE = "Spawns in the middle of the Den (fly down to 51.21, 52.93) after all 3 altar rituals. For each: pick up the nearby item, sacrifice it at the altar, then SPEAK to the spirit that appears and pick 'offer item'. Wisdom: Rolled-Up Pillow (51.39, 56.0) -> altar 51.15, 58.56. Vigor: Lost Hunting Knife (45.14, 54.12) -> altar 47.18, 53.14. Innocence: Tattered Ball (51.10, 50.49) -> altar 51.15, 47.55.",
	ACH_NOTE_HONOREDURNS = "Fill the cache by looting the 4 Honored Warrior's Urns around Zul'Aman; each spawns a Chosen miniboss that drops the token, then return to the cache.",
	ACH_NOTE_SEALINGORBS = "Destroy the 4 Sealing Orbs around the chest to unseal it.",
	ACH_NOTE_BAITTACKLE = "In the back of a small cave (entrance ~21.1, 67.1).",
	ACH_NOTE_STRANGER = "Under the bridge, not on it — the memorial sits below the walkway, so a route that lands you on top of it will look like nothing is there.",
	ACH_NOTE_BURROW = "In a small cave.",
	ACH_NOTE_MRRUK = "Guarded by the miniboss Mrruk the Musclefin - defeat it first, then loot the trove.",
	ACH_NOTE_PREDAXAS = "In a small cave (entrance ~48.96, 78.33). Inside you get the Disruptive Ozone debuff (no spells/abilities) - cross the electrified egg clutch without touching the glowing ground circles to reach the chest.",
	ACH_NOTE_VOIDTOMB = "Requires level 90. Drink the Potion of Dissociation on the nearby table, then run to the opposite building, grab the Key of Fused Darkness and unlock the chest.",
	ACH_NOTE_BLOODYSACK = "Collect Dripping Meat from nearby bone piles to feed the Forgotten Oubliette.",
	ACH_NOTE_MALIGNANT = "Enter the cave at 53.21, 44.19. Only one Malignant Node is active at a time - activate them in turn (1 -> 2 -> 3 -> 4) until the chest appears.",
	ACH_NOTE_STELLAR = "In Slayer's Rise: click the cave door at 52.21, 31.16 to open it, then head in keeping right to ~53.18, 32.21 and click/pull it 3 times to make the stash appear.",
