	CONSREADY_BAG_UNKNOWN = "bag unknown",
	CONSREADY_FOOTER = "|TInterface/RAIDFRAME/ReadyCheck-Ready:0|t present/active · |TInterface/RAIDFRAME/ReadyCheck-NotReady:0|t missing · |TInterface/RAIDFRAME/ReadyCheck-Waiting:0|t unknown. Group members show buff status only — the API can't read others' bags (bag sharing comes in Phase 2). /mh readytoggle to mute.",
