	AURADUMP_HEADER = "Your active buffs (spellID — name):",
	AURADUMP_NONE = "No active buffs.",
	AURADUMP_DEBUFF_HEADER = "Your active debuffs (spellID — name):",
	TAB_ENCHANTS = "Enchants & Gems",
	ENCHANT_SUBTITLE = "A quick check of your equipped gear: enchantable slots missing an enchant, plus items with empty gem sockets — each with a stat-matched Midnight suggestion for your spec. Updates as you re-gear.",
	INFO_DRAWER_BODY_ENCHANTS = "Scans your enchantable slots (weapon, chest, helm, shoulders, rings, boots, legs) and flags any without an enchant. Rings and weapon get a suggestion matching your spec's top secondary stat (from the Vault Advisor weights); chest, legs and tertiary slots are generic. For pure best-in-slot, check a class guide. Cloak, wrist and belt aren't enchantable this patch. It also checks empty gem sockets: socket one unique Eversong Diamond (+32 primary stat — only one allowed) plus a stat-matched dual gem in your other sockets.",
	TAB_CURRENCY = "Currencies",
	CURRENCY_QM_LABEL = "Renown Quartermaster waypoint:",
	CURRENCY_QM_COURT = "SMC Court",
	CURRENCY_QM_AMANI = "Amani",
	CURRENCY_QM_HARATI = "Hara'ti",
	CURRENCY_QM_SINGULARITY = "Singularity",
	TAB_TIER = "Tier Sets",
	TIER_SUBTITLE = "What tier sets are, how to get them, and your set's bonuses with a live 2-set / 4-set tracker.",
	INFO_DRAWER_BODY_TIER = "Explains Midnight's tier sets: the 5 set slots, the 2- and 4-piece bonuses, and how to get them (raid tokens, the Great Vault, the Matrix Catalyst). Shows your class set with clickable bonus links and counts how many tier pieces you have equipped. Set-bonus values are datamined for 12.0.7 — hover a link for the live tooltip.",
	TIER_GUIDE_BODY = "|cffe8c36aWhat tier sets are|r|n• 5 special slots — head, shoulders, chest, hands, legs — that give a bonus at 2 and 4 pieces. The 4-set is usually a big power gain, so it's normally your first goal (often worth more than a few item levels).|n• You only need 4 of the 5; leave whichever slot holds your strongest non-tier item. Wrist, belt, boots, neck, rings, cloak and weapons are never tier — always take the best raw upgrade there.|n|n|cffe8c36aHow you get them|r|n• Raid drops: The Voidspire bosses 2–5 each drop a class token (hands, shoulders, legs, helm). The chest piece comes from The Dreamrift.|n• Great Vault: clear 2/4/6 raid bosses in a week to unlock vault picks.|n• {CATALYST} (Silvermoon): converts an eligible non-set head/shoulder/chest/hands/legs piece into the tier slot you need. Unlock it once from Eldara Dawnrunner (quest 'Taste True Power'); each conversion spends one Dawnlight Manaflux. You get your first charge in week 1, then one more every 2 weeks. Once you reach 4-set, charges also start dropping from raids, M+, Bountiful Delves and rated PvP.|n|n|cffe8c36aNew-player path|r|n• Run LFR Voidspire weekly for token shots, fill your Great Vault, and spend a Catalyst charge on the slot you're missing. Most players reach 2-set fast (one drop + one Catalyst), then finish 4-set from the Vault or a second Catalyst charge.",
	TIER_YOUR_SET = "Your set:",
	TIER_2SET = "2-set bonus:",
	TIER_4SET = "4-set bonus:",
	TIER_COUNT_FMT = "Tier pieces equipped: %d/5",
	TIER_COUNT_UNKNOWN = "Equip a tier piece to track your 2-set / 4-set progress here.",
	TIER_SET_UNKNOWN = "(your spec's set bonus isn't mapped yet — check it in-game)",
	TIER_FOOTER = "Set-bonus values are datamined for 12.0.7 and still being tuned — hover a link for the live tooltip and confirm in-game.",
	TIER_CATALYST_NAME = "Matrix Catalyst",
	CURRENCY_SUBTITLE = "Earned where, spent where: a quick map of every Midnight currency and which vendor takes it.",
	INFO_DRAWER_BODY_CURRENCY = "Lists each Midnight currency: how you earn it and which vendor takes it. Click a currency name to open your live total. Gear-upgrade crests have their own tab with the full ladder.",
	CURRENCY_GUIDE_BODY = "|cffe8c36aVoidlight Marl|r — {CURRENCY:3316}|n• Earn it from: rares, world quests, delves, Prey hunts, Ritual Sites and their paragon cache.|n• Spend it at: the four Renown Quartermasters out in the zones (listed below), plus mount/pet/cosmetic and housing vendors. Warband-transferable between your characters.|n|n|cffe8c36aField Accolade|r — {CURRENCY:3405}|n• Earn it from: Ritual Sites and Void Assaults.|n• Spend it at: Maren Silverwing for Void-Touched GEAR caches (Champion 75 / Hero 500), or Triam Dawnsetter for cosmetics only. Not warband-transferable.|n|n|cffe8c36aCrests (gear upgrades)|r|n{CRESTS}|n• Earn them from: outdoor content, delves, dungeons and raids (higher content = higher tier).|n• Spend them at: Cuzoth (upgrade gear) and Vaskarn (trade crests up or down a tier) in the Bazaar. See the Crest tab for the full ladder.|n|n|cffe8c36aPvP currencies|r|n• Honor → Aspirant gear (Captain Dawnrunner).|n• Conquest → Champion gear (Irissa Bloodstar).|n• Bloody Tokens (War Mode) → Veteran gear (Knight-Lord Bloodvalor).|n• Marks of Honor → Gladiator cosmetics (Soryn). The PvP vendors sit on the west side of Silvermoon, near Falconwing Square.|n|n|cffe8c36aRenown Quartermasters (spend Voidlight Marl)|r|n• Silvermoon Court — Caeris Fairdawn (Saltheril's Haven, Eversong Woods).|n• Amani Tribe — Magovu (Zul'Aman).|n• Hara'ti / Haranir — Naynar (The Den, Harandar).|n• The Singularity — Void Researcher Anomander (Voidstorm).|n|n|cff9aa0a8Vendor names, costs and locations from Wowhead/Method research (15 Jun) — confirm in-game. Currency names link to your live totals.|r",
	DELVELOG_CLEAR = "Clear Log",
