	-- Patch 12.0.7 codex articles
	CODEX_127_SHOWDOWNS_TITLE = "Showdowns: Naigtal & Val (12.0.7)",
	CODEX_127_SHOWDOWNS_BODY = "A portal in the Voidstorm (Screaming Ridge) leads to one of two rotating Void worlds: fungal Naigtal or frozen Val. Each offers world quests, rares, zone events and a world boss (Nexus-Captain Leth'ir / Imperator Pertinax). The Showdown weekly awards a Riftstalker's Cache and counts toward the Great Vault World row. Optional Heroic World Tier raises difficulty and rewards — pick it at the portal. Start with Riftblade Maella in Silvermoon City.",
	CODEX_127_SPOREFALL_TITLE = "Sporefall Raid (12.0.7)",
	CODEX_127_SPOREFALL_BODY = "Single-boss raid in Harandar: Rotmire, a fungal giant. Same Season 1 tier with higher item levels (LFR 259 / Normal 272 / Heroic 285 / Mythic 298); Mythic is flexible with 15-25 players. Pick up a Delicious Sporesnack once per week on any difficulty — four in total buys the Luminous Sporeglider mount.",
	CODEX_127_FOLIO_TITLE = "Omnium Folio & Runes (12.0.7)",
	CODEX_127_FOLIO_BODY = "New power system that takes no gear slot. Unlock it via the Sunstrider Omnium questline with Magister Umbric and Grand Magister Rommath on Quel'Danas. Each week the 'Seeking Knowledge' quest grants a Mote of Omnial Inquiry to unlock one of five rune rows; runes swap freely out of combat.",
	CODEX_127_TIMEWAYS_TITLE = "Turbulent Timeways V (Jun 30 - Aug 11)",
	CODEX_127_TIMEWAYS_BODY = "Timewalking marathon featuring six Dragonflight dungeons. Run four dungeons in a week for that week's Mastery buff; earn Mastery in four separate weeks to claim the Spawn of Vyranoth mount.",
	CODEX_127_RITUALRENOWN_TITLE = "Ritual Sites Renown (12.0.7)",
	CODEX_127_RITUALRENOWN_BODY = "Ritual Sites have an account-wide renown track (8 ranks) in the Journeys window. Ranking up makes every site richer: healing Regeneration Orbs, then rare enemies (rank 4), buff shrines (rank 5), bigger treasures (rank 7) and rare elites (rank 8) — all dropping extra spoils. It also unlocks Silvermoon vendor goodies: void housing decor (rank 3, Rae'ana), pets (rank 6, Sergeant Vornin) and the Void-Touched Hawkstrider mount (rank 8, Sergeant Vornin). Every reward is Warband-wide, so your progress counts for the whole account. Click the glowing Loa Shrines inside a site for a 60-minute stat buff (e.g. +10% critical strike).",
	TAB_BETA_BADGE = "Beta",
	TAB_BETA_TOOLTIP_TITLE = "Work in progress",
	TAB_BETA_TOOLTIP_BODY = "This tab is early beta — content is incomplete, may change often, and is not ready for full use yet.",
