	ACADEMY_PREF_HEAL_CONSUMABLES = "Mana pot / flask (Consumables tab)",
	ACADEMY_PREF_HEAL_PRACTICE = "Practiced hover-heal on a friend once",
	ACADEMY_PREF_DPS_ROTATION = "Main abilities on easy-to-reach keys",
	ACADEMY_PREF_DPS_COOLDOWNS = "Damage cooldowns keybound (not lost on the bar)",
	ACADEMY_PREF_DPS_DEFENSIVE = "A personal defensive on my bar",
	ACADEMY_PREF_DPS_INTERRUPT = "My interrupt keybound (dummy test once)",

	ACADEMY_TANK_INTRO_TITLE = "Tank mindset",
	ACADEMY_TANK_INTRO_BODY = "Your job is to set pace and hold attention - not to top damage meters.\n\nOne steady pull beats a perfect rotation on a dead group. Say pulls out loud if it helps: \"pulling in 3\".",
	ACADEMY_TANK_PULL_TITLE = "During a pull (first 10 seconds)",
	ACADEMY_TANK_PULL_BODY = "1. Grab the pack (taunt / threat).\n2. Face enemies away from the group when you can.\n3. Use one defensive if damage spikes - save the second for \"oh no\".\n4. Interrupt the cast that hurts most (often heal or big hit).\n\nYou do not need every ability on cooldown immediately.",
	ACADEMY_TANK_WIPE_TITLE = "When it goes wrong",
	ACADEMY_TANK_WIPE_BODY = "A wipe is data, not a verdict. Ask: \"Was I too far ahead?\" or \"Did I save a defensive?\"\n\nRepair, eat, try again.",
	ACADEMY_TANK_DUNGEON_TITLE = "Your first dungeon (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Start normal with friends or guildies if you can. Go slow on pulls - two small packs beat one huge chain.\n\nWatch the healer's mana; pause between pulls. It is OK to ask for CC or \"no big pull yet\".",
	ACADEMY_TANK_RAID_TITLE = "Raids and LFR (later)",
	ACADEMY_TANK_RAID_BODY = "LFR is the gentle raid intro: forgiving, many healers. Focus on boss taunt timings and standing still in the right place.\n\nMythic raid tanking is not the next step - comfort in heroic/LFR first.",
	ACADEMY_TANK_CHAT_TITLE = "Party chat",
	ACADEMY_CHAT_HINT = "Click a line or the copy icon, then Ctrl+C to paste in party chat.",
	ACADEMY_CHAT_COPY_TIP = "Select this line (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Still learning tank - go slow please.\"\n\"Pulling in 3...\"\n\"Need a breather for mana.\"\n\"Interrupt on [spell name] - I have it next.\"\n\"One more try - I know that pull now.\"",
	ACADEMY_TANK_LADDER_TITLE = "Anxiety ladder (recommended order)",
	ACADEMY_TANK_LADDER_BODY = "1. Open world elites with a friend\n2. Delves (smaller instance - Delves tab)\n3. Normal dungeon with people you trust\n4. Heroic / LFR when comfortable\n\nSkip a step until it feels boring, not terrifying.",
	ACADEMY_TANK_BOTH_TITLE = "Learning heal or DPS too?",
	ACADEMY_TANK_BOTH_BODY = "The DPS track is the gentlest second role - your rotation, kicks and positioning, with no group depending on you. Healing is the bigger jump, but you already read pulls, and that is half of it.\n\nPick one main role in dungeons for a while and practise the other in delves or open world. Switching roles in the same M+ pug doubles the stress; mastery in one first builds confidence for the second.",

	ACADEMY_HEAL_INTRO_TITLE = "Heal mindset",
	ACADEMY_HEAL_INTRO_BODY = "You are not responsible for everyone at 100% health all the time.\n\nYour job is triage: keep the tank alive, save the person about to die, then the rest. Some damage is normal - panic overhealing empties mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triage (who first?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. You (if you're dying - dead healer heals nobody)\n2. Tank (if the pack is still on them)\n3. Anyone under ~40% or with a deadly debuff\n4. Everyone else with efficient heals\n\nBig heal after big damage; small heals between events.",
	ACADEMY_HEAL_WIPE_TITLE = "When it goes wrong",
	ACADEMY_HEAL_WIPE_BODY = "\"Could I have saved the tank?\" is the useful question - not \"why did DPS stand in fire?\"\n\nIf mana was empty, use more efficient spells next time. One wipe does not mean you cannot heal.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Your first dungeon (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Tell the group you are learning. Stand in range of the tank; let DPS take a scratch before you blast mana.\n\nBetween pulls: drink, buff, breathe. You are allowed to say \"oom, 5 sec\".",
	ACADEMY_HEAL_RAID_TITLE = "Raids and LFR (later)",
	ACADEMY_HEAL_RAID_BODY = "LFR: raid-wide damage is predictable after one wipe. Learn the fight timer, not every player's bars.\n\nRaid heals use the same triage - tank and raid cooldown windows first.",
	ACADEMY_HEAL_CHAT_TITLE = "Party chat",
	ACADEMY_HEAL_CHAT_BODY = "\"Learning healer - I'll call low mana.\"\n\"Tank is priority - shout if you need a breather.\"\n\"Big heal on you - watch your health.\"\n\"Oom 5 sec between pulls.\"\n\"That was on me - I'll save more for the tank next pull.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Anxiety ladder (recommended order)",
	ACADEMY_HEAL_LADDER_BODY = "1. Heal a friend in open world\n2. Delves with a small group\n3. Normal dungeon with patient friends\n4. Raid LFR / heroic when ready\n\nDelves are the softest step into instanced content.",
	ACADEMY_HEAL_BOTH_TITLE = "Learning tank or DPS too?",
	ACADEMY_HEAL_BOTH_BODY = "The DPS track is the gentlest second role - just your rotation, kicks and positioning, no pressure on the group. The Tank track gives the fastest dungeon queues once tanking feels less scary.\n\nTwo roles in one week in pugs is a lot - pick one as your \"main\" to reduce fear.",
	ACADEMY_DPS_BOTH_TITLE = "Thinking about tank or heal?",
	ACADEMY_DPS_BOTH_BODY = "You already know the fights from the DPS seat, and that is most of the work. Tanking gives you instant dungeon queues; healing asks the most nerve but is the most wanted.\n\nTry the new role in a delve or a follower dungeon first, where nobody is waiting on you. Then keep one role as your main for a while instead of swapping every pug.",

	-- Deepened beginner heal course (healer initiative, piece 2)
	ACADEMY_HEAL_MANA_TITLE = "Mana and efficiency",
	ACADEMY_HEAL_MANA_BODY = "Mana is your real health bar. If you empty it, you can't heal at all.\n\nUse cheap, fast heals for small dips; save your big, expensive heals for real emergencies. Not everyone needs to sit at full - let people ride at 80%.\n\nDrink between every pull. \"Oom, 5 sec\" is a normal, professional thing to say.",
	ACADEMY_HEAL_POSITION_TITLE = "Where to stand",
	ACADEMY_HEAL_POSITION_BODY = "Stay in range of the whole group, but not on top of the boss. A back corner where you can see everyone beats hugging the tank.\n\nYou still have to dodge. A dead healer heals nobody - step out of the bad stuff even if it costs half a second of casting.\n\nKeep line of sight: you can't heal someone through a wall or pillar.",
	ACADEMY_HEAL_COOLDOWNS_TITLE = "Save your big cooldowns",
	ACADEMY_HEAL_COOLDOWNS_BODY = "Your big healing cooldowns are for big, planned damage - a boss's raid-wide hit - not for random scratches.\n\nHolding a cooldown \"just in case\" for the whole fight wastes it. A cooldown pressed at 90% of the right moment beats one never pressed.\n\nType /mh healcds for your spec's cooldowns and when to save each one.",
	ACADEMY_HEAL_MISTAKES_TITLE = "Common beginner mistakes",
	ACADEMY_HEAL_MISTAKES_BODY = "1. Tunnel-visioning one health bar while three others drop\n2. Panic-overhealing to 100% and emptying mana\n3. Standing in the bad stuff while staring at frames\n4. Never pressing your cooldowns\n5. Healing through fixable damage instead of asking for an interrupt\n\nPick one to watch each run - not all five at once.",
	ACADEMY_HEAL_CONFIDENCE_TITLE = "It's okay to lose someone",
	ACADEMY_HEAL_CONFIDENCE_BODY = "Someone will die on your watch. Every healer alive has let people die - it's how you learn where the limits are.\n\nOne death is not a wipe, and a wipe is not a verdict on you. Note the one thing you'd do differently, then let it go.\n\nGroups remember a calm healer who communicates far more than a perfect one.",

	-- DPS track (Role Academy DPS role)
	ACADEMY_DPS_INTRO_TITLE = "DPS mindset",
	ACADEMY_DPS_INTRO_BODY = "Your job is damage - but a dead DPS does zero. Staying alive and doing mechanics comes first, damage second.\n\nYou don't need the top of the meter. Steady damage while doing your job beats huge numbers followed by a death.",
	ACADEMY_DPS_ROTATION_TITLE = "Priority, not a fixed rotation",
	ACADEMY_DPS_ROTATION_BODY = "Most specs build a resource, then spend it. Keep your builder and spender flowing; don't cap your resource and don't let dots/buffs fall off.\n\nOne or two buttons pressed at the right time beats mashing five. Learn the priority, not a memorized order.",
	ACADEMY_DPS_COOLDOWNS_TITLE = "Line up your cooldowns",
	ACADEMY_DPS_COOLDOWNS_BODY = "Your damage cooldowns are most of your damage. Pressing them on cooldown beats saving them for a \"perfect\" moment that never comes.\n\nOn a boss, open with them or save them for the phase that matters. Your toolkit above lists them for your spec.",
	ACADEMY_DPS_MECHANICS_TITLE = "Mechanics beat damage",
	ACADEMY_DPS_MECHANICS_BODY = "Move out of the bad stuff even if it costs a cast. A stack of avoidable damage wipes the group faster than low DPS does.\n\nGreedy is standing in fire for one more cast. Good is taking half a second to reposition and living to press the rest.",
	ACADEMY_DPS_UTILITY_TITLE = "You're not just a damage bot",
	ACADEMY_DPS_UTILITY_BODY = "Interrupt dangerous casts, use your crowd control, and press your personal defensive when you take a big hit.\n\nA DPS who kicks and survives is worth far more than one who only pumps numbers.",
	ACADEMY_DPS_MISTAKES_TITLE = "Common beginner mistakes",
	ACADEMY_DPS_MISTAKES_BODY = "1. Sitting on cooldowns \"just in case\"\n2. Capping your resource (wasted generation)\n3. Standing in the bad stuff for one more cast\n4. Never interrupting or using utility\n5. Tunnel-visioning damage while your health bottoms out\n\nPick one to fix each run - not all five at once.",
	ACADEMY_DPS_PRACTICE_TITLE = "Target practice",
	ACADEMY_DPS_PRACTICE_BODY = "Hit a training dummy for two minutes: keep your resource flowing, weave your cooldowns, and watch what falls off.\n\nThen delves, then normal dungeons. You don't need a perfect rotation to start - you need to keep pressing and stay alive.",

