	LAYOUT_LEGEND = "|cff33ff61Green|r = move (W A S D).\n|cffe0e070Gold|r = spells & shortcuts on this map.\n|cff8ecfff+N|r = extra Shift/Ctrl binds - hover the key.\n|cff59d9ffTab|r = switch targets quickly.\n|cffe0e070M4-M9|r = your mouse thumb buttons.\n|cff888888Grey|r = not on this starter map.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Opened from your leveling guide — this key is on the Midnight map.|r",
