	MODULE_PLACEHOLDER = "Module placeholder — content for \"%s\" will mount here.",
	INFO_DRAWER_TOGGLE_SHOW = "Info",
	INFO_DRAWER_TOGGLE_HIDE = "Close",
	INFO_DRAWER_TITLE_FMT = "%s - How to use",
	INFO_DRAWER_BODY_DELVES = "Midnight Delves command center for your current character.\n\nExpand Great Vault for weekly reward tracking, or Midnight Delves for season currencies (Restored Coffer Keys, weekly Shards, Undercoins), Delver's Journey / renown, and the full delve roster with live bountiful detection from map POIs.\n\nNavigation: right-click a row to route to the entrance. |cffffcc00TomTom (recommended)|r adds the map arrow and waypoint queue. |cff00ff00Travel Assistant|r (popup when you are far away) shows Hearthstone and hub portal shortcuts and works |cffffff00without|r TomTom.\n\nFind Nearest Bountiful requires TomTom to be installed.",
	INFO_DRAWER_BODY_ACCOUNT = "Cross-character roster stored locally by this addon (saved variables on your PC—not Blizzard cloud sync).\n\nEach row lists Keys, Shards, Undercoins, professions echo, and a compact Great Vault summary with rich tooltips; your logged-in character is highlighted and sorting favors usefulness.\n\nRows refresh on login and currency / weekly events. Delete only removes addon snapshot data—never your actual WoW character.",
	INFO_DRAWER_BODY_RARES = "Midnight world rares by zone (Eversong, Zul'Aman, Harandar, Voidstorm).\n\nPick a zone in the left column. Rare rows show green = done on this character, green UP = map vignette near the spawn (likely spawned now), grey dash = not on your map data yet.\n\nFind Nearest Rare routes to one pin; Generate Route queues all incomplete rares in TomTom (nearest first, like Professions). Vignette UP is best-effort — open the zone map or move closer if it looks wrong.",
	RARES_TITLE = "Midnight rares",
	RARES_SUBTITLE_FMT = "%d/%d done on this character · %d visible on map now (silver star)",
	RARES_EMPTY_ZONE = "No rare list for this zone.",
	RARES_BTN_NEAREST = "Find Nearest Rare",
	RARES_BTN_ROUTE = "Generate Route",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper:|r TomTom: nearest rare — %s",
	RARES_NEAREST_NONE = "No incomplete rares left in this zone.",
	RARES_NEAREST_NO_TRAVEL = "Travel Assistant unavailable (Delves module not loaded).",
	RARES_ROUTE_DONE_FMT = "Queued %d/%d incomplete rares in TomTom. %s",
	RARES_SKIP_DONE_FMT = "Skipped %s — arrow moved to the next rare (you'll come back to it).",
	RARES_SKIP_LAST = "That's the last open rare — nothing to skip to.",
	RARES_SKIP_SINGLE = "Skip works during Generate Route (it chains past un-spawned rares).",
	ARROW_OTHER_CONTINENT = "(other continent — travel back)",
	ARROW_LEAVE_INSTANCE_FIRST = "(leave here first)",
	ARROW_FLY_TO = "head for %s",
	ARROW_AT_STEP = "You are at %s — go through, the arrow picks up on the other side.",
	-- Short on purpose: it sits on the arrow label beside a name and a distance.
	ARROW_TARGET_ROAMS = "|cffffd100(roams — look around)|r",
	RARE_SPAWN_FROM_CHEST = "|cffffd100(open the chest to summon him)|r",
	ROUTE_CLEARED = "Route cleared.",
	ROUTE_CLEAR_NONE = "No active route to clear.",
	RARES_ROUTE_ORDER_NEAR = "Order: nearest first, then next closest each step.",
	RARES_ROUTE_ORDER_LIST = "Order: list order (position unavailable).",
	RARES_TAG_UP = "UP",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Done this week on this character (resets Wednesday).",
	RARES_TIP_UP = "Likely up now (map vignette near spawn point).",
	RARES_TIP_DOWN = "Not seen on map right now — may still spawn later.",
	RARES_TIP_VIGNETTE_NOTE = "Vignette status is best-effort; open the zone map or get closer if unsure.",
	INFO_DRAWER_BODY_SMC = "Silvermoon City reference for Midnight (map 2393). The same scroll starts with the Weekly / hub checklist when quest IDs are configured, then continues into categorized pin grids—Essential Services, Travel, Quest hubs, Profession trainers, Gathering, and more.\n\nEach location button sets Blizzard's user waypoint and, with TomTom installed, mirrors it through the slash helper (/way #2393 …).\n\nChecklist progress tints related waypoint buttons green; update quest IDs in data after major patches if a row looks wrong.",
	INFO_DRAWER_BODY_PROFESSIONS = "Tracks Midnight profession Knowledge Points (KP) for your current character, plus currency lines when the client exposes them (Unalloyed Abundance, Artisan's Moxie, weekly Shards of Dundun).\n\nBelow that, two columns list Knowledge Pickup quests and profession books per trade—icons show whether each quest is complete. Click a row to send only that pin to TomTom (clears other waypoints; Travel Assistant handles cross-zone hops when TomTom is loaded).\n\nBottom buttons batch-queue incomplete pins: Generate Treasures or Generate Books (nearest unfinished first when your map position is available).",
	INFO_DRAWER_BODY_GUIDE = "Spec-by-spec leveling references styled after Icy Veins: stat priority, gear picks, consumables filtered to what your level can actually use, optional spell tip rows, and the Leveling Advisor with bracket tabs for rotation, defensives, and talent focus.\n\nWhen your class has a Midnight key map (Hunter / Paladin for now), tips can show a gold key button — click it to open the Layout tab and highlight that key on the keyboard. That links reading (what to press) to placement (where on the keyboard), so you learn by doing.\n\nThe global search bar understands guide keywords and can jump between Midnight Helper tabs; Preview lets you read another specialization without relogging while My character snaps back to your active spec.\n\nGuide tab visibility follows Settings: Auto (hides at level 90+), Always show, or Always hide.",
	INFO_DRAWER_BODY_MACROS = "Interrupt tab: team kick macro (focus first). Utility tab: extra spec macros (cursor ground spells, mouseover heals, and similar) from the team pack. Pick a row, read the tip, copy the text.\n\nData can change after patches - report missing spells to the team.",
	INFO_DRAWER_BODY_ADDONS = "Hub for optional tools bundled inside Midnight Helper rather than separate downloads.\n\nChoose a sub-tab along the top—today that is Platynator: Wago link, profile-string import, and the MF Platynator visual gallery.\n\nAdditional partner panels register here automatically when future modules ship.",
	ABOUT_WINDOW_TITLE = "About Midnight Helper",
	ABOUT_VERSION_FMT = "Installed version: |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Authors: TwelveInchy & Claude\n\nYour all-in-one Midnight companion, organised into four rooms — Me, Codex, Tools and Settings. Pin favourites under the search bar and type to jump anywhere. Includes This Week, Delves & Vault, Delve & Ritual coaches, the Enchants & Gems advisor, Account snapshot, Codex guides, Professions and integrated addon tools — EN / NL / DE / FR / ES / PT / IT.\n\nWith thanks to the addons and guides we checked our facts against: EXBoss and EXBossData (raid boss key casts), HandyNotes_Midnight (rare and treasure locations), GTFO (hazard spell ids), RareScanner (vignette handling), and Wowhead, Icy Veins and Method. We take ids and numbers as leads and confirm them against the game client before they ship here; no code from these addons is used.",
	MAIN_TITLE_VERSION_FMT = "v%s",
	BROKER_TOOLTIP_VERSION_FMT = "Version: %s",

	CHANGELOG_TITLE = "Midnight Helper Changelog",
	CHANGELOG_SUBTITLE = "Version %s",
	CHANGELOG_VERSION_FMT = "Version %s",
	CHANGELOG_CLOSE = "Close",
	CHANGELOG_CB_UNTIL_NEXT = "Do not show again until next version",
	CHANGELOG_CB_NEVER = "Permanently hide changelog",
	CHANGELOG_120_1 = "Added compact Leveling Advisor panel with per-level brackets and tabs (Rotation / Defensives / Talent focus).",
	CHANGELOG_120_2 = "Improved consumables section: only shows usable items at your current level and explains next unlocks.",
	CHANGELOG_120_3 = "Added Account Snapshot row management: delete stale characters safely (with confirmation) plus zebra-striping.",
	CHANGELOG_120_4 = "Improved localization consistency (EN/NL) and added in-guide stat glossary via the new ? Stats button.",
	CHANGELOG_121_1 = "Main window: inner panels respect the gold dialog frame—corner ornaments stay visible and the bottom/right “empty gutter” next to the resize grip is gone.",
	CHANGELOG_121_2 = "Info and About use standard Blizzard panel buttons again (same treatment as Search / My character) for a consistent look on all clients.",
	CHANGELOG_121_3 = "Minor polish only; Delves, Vault, guides, and localization behavior unchanged—safe drop-in update.",
	CHANGELOG_122_1 = "Macros tab: one-click team interrupt macro plus curated utility macros per spec (cursor, mouseover, focus)—copy, paste, play.",
	CHANGELOG_122_2 = "Preview any spec without relogging: guide search updates leveling tips, keyboard layout, and macros for that class/spec in one go.",
	CHANGELOG_122_3 = "Guide search and chat messages follow your language choice (/mh lang en or nl).",
	CHANGELOG_122_4 = "Midnight key layout refresh: interrupt on E, clearer role slots, smarter overflow (Alt, Shift, Ctrl).",
	CHANGELOG_122_5 = "Still cooking: everything in Midnight Helper is subject to change and steady improvement—patches will keep landing. Feedback welcome!",
	CHANGELOG_182_4 = "New Omnium Folio tab: the full 12.0.7 rune tree with clickable spell tooltips, a recommended pick per row for M+/Raid/PvP/World, the unlock walkthrough, and a live x/5 rows-unlocked counter. The Account snapshot checklist also reminds you (account-wide) to do this week's Folio Mote until you're fully unlocked.",
	CHANGELOG_185_1 = "New setting: hide the weekly Coffer Shard cap popup (Settings -> Dungeon). Thanks to gadrinonturalyon for the request!",
	CHANGELOG_185_2 = "New setting: show or hide the 3D boss model in the boss window (Settings -> Dungeon). Also requested by gadrinonturalyon.",
	CHANGELOG_185_3 = "New language: Italian (itIT) — interface and guides translated. Auto-selects on an Italian WoW client, or pick it with /mh lang it. (Older changelog entries stay English.)",
	CHANGELOG_185_4 = "Fixed: the world boss \"Warband: defeated this week\" line now shows on all your characters once any one of them kills it (account-wide check), not only on the looter — and remembers which character did it.",
	CHANGELOG_185_5 = "Fixed: the weekly Coffer Shard cap popup now appears only once per character per week. You may see it one more time after this update, then it stays off until the next reset (when you hit the cap again).",
	CHANGELOG_185_6 = "New in Professions 101: a 'Skill leveling 1-100' route per profession (Alchemy & Herbalism first, more coming) and a clear 'Work Orders explained' chapter - how to order items and craft for others.",
	ACH_NOTE_UNDERBELLY_STRIKE = "Only up while the Temple Strike: The Underbelly is running - there is no fixed spot to walk to, so the arrow leaves this one alone.",
	ACH_NOTE_ANCIENT_FOE = "Spawns where a Temple Incursion finishes, so it has no place on the map. Join whatever is running and it comes to you.",

	ACH_NOTE_VSERIX ="Wanders, and can be killed without any event running.",
	ACH_NOTE_MIX_MASTER = "One per day, crafted at Ofi the Sly's cauldron at 57.4 / 48.7 - not the Ofi in the swamp, who cannot mix. Each offering is an exact three-ingredient combination and the game shows you nothing while you pick, so the recipe below is the whole job. Ingredients come from Cracked Canopic Jars, Venom-Clotted Baubles and Singing Shells around the isle, and they are tradable, so the auction house works too.",
	ACH_NOTE_MIX_GATES = "Two things gate this. Renown 3 with Zul'jarra's Forces makes the containers appear at all, and the Ofi's Offerings node on the Altar of Corrosion is what puts ingredients inside them - with the first and not the second you will loot nothing and think it is broken.",
	ACH_MIX_RECIPE_FMT = "Needs: %s",

	ICV_KEYS_TITLE ="The four Altar of Corrosion nodes you cannot buy",
	ICV_UNLOCK_ANCIENT_FOE = "Drops from any Ancient Foe, at the end of a Temple Incursion.",
	ICV_UNLOCK_TEMPLE_STRIKE = "Drops from Temple Strikes.",
	ICV_UNLOCK_TEMPLE_INCURSION = "Drops from Temple Incursions.",
	ICV_UNLOCK_JINTAL = "From High Priest Jin'tal, in the Vault of Restless Brothers - he turns up in the side questline The Med'jai Medallion.",
	ICV_WHERE_TOKJARA = "On a ledge to the right of the Venomous Abyss raid entrance.",
	ICV_WHERE_LYNX = "In chests beneath the poison waterfalls.",
	ICV_WHERE_SZARITH = "North side of the Underbelly, in a round poison pool.",
	ICV_WHERE_MEDJAI = "East side of the Profaned Mausoleum - left after you enter, in a chest on a shelf.",
	ICV_SPOTS_PREFIX = "Nine places it can be:",
	ICV_ALSO_CALLED = "Elsewhere called:",
	ICV_DISPUTE_MEDJAI = "Sources disagree on the second option: we wrote 'get straight back up when you die outside the Vaults', Icy Veins calls it an instant res inside Atal'Utek. Nobody has measured it.",
	ICV_SOURCE_NOTE = "Drop sources and coordinates from Icy Veins, 16 Aug - one source, not yet verified in-game. The Feather of Tok'jara is the exception: our own July notes give the same two numbers.",

	HAZARD_SECTION_FMT ="Do not stand in this (%s)",
	HAZARD_OUTSIDE ="You are not in an instance, so there is no list for here.",
	HAZARD_WORLD_COUNT = "hazards are known for Midnight's outdoor content, but not which zone each belongs to.",
	HAZARD_NONE_KNOWN = "nothing is known about what hurts you here yet.",
	HAZARD_COUNT = "things not to stand in",
	HAZARD_SOURCE_NOTE = "Names come from your own client. That each belongs to this place is GTFO's data, not measured.",

	CHANGELOG_350_1 = "The languages are done. German, French, Spanish, Portuguese and Italian now read as their own language throughout - the whole professions course, the Codex, the dungeon and delve guidance, the academy, the commands and the achievement text, roughly thirty thousand characters each. Short labels stay English on purpose: stat names, DPS, Flask, Bountiful, and anything Blizzard writes in English in your client anyway.",
	CHANGELOG_350_2 = "They use your client's words, not ours. Every game term was checked against Blizzard's own game data, and four were wrong: the Italian course called the Deftness stat Destrezza when the Italian client calls it Velocità, and Crafting Details, Patron and Recipe Difficulty had been left in English in French, Spanish and Portuguese.",
	CHANGELOG_350_3 = "Fixing a sentence in English does not reach the other five languages - a pack that already has the line keeps its own, silently. Seven strings were sitting like that, including the work orders chapter still saying four public orders per day in five languages, which is the exact error 3.4.0 announced fixing. Corrected, and the check now runs the addon's own resolver instead of counting keys.",
	CHANGELOG_350_4 = "Valeera's progress now shows while you are in a delve: where she is, and what the bar cannot tell you - what a bountiful run is actually worth, measured from your own recent runs. It does not pretend that is a fixed number: a run is worth what the delve and your pickups make it, so once your runs disagree you get the range instead of one tidy figure. Healer is still the recommendation, but the reason it is one now depends on what you play. The X closes the popup for good rather than for that delve only; /mh valeera brings it back.",
	CHANGELOG_350_5 = "Standing next to a portal no longer gets you routed to a flight master. The travel hint asks the travel planner first, so a portal is reported as the first step when it is one, and the arrow points at it and then hands back to your real destination afterwards.",
	CHANGELOG_340_1 = "Professions 101 is now an actual beginner course. Six new or rewritten chapters: what quality is and why the same recipe gives two players different results, what those six numbers on your screen mean (Multicraft, Resourcefulness, Ingenuity, Finesse, Perception, Deftness), Concentration and when it is worth spending, work orders, patron orders, and making gold without fooling yourself.",
	CHANGELOG_340_2 = "That course is 14 chapters now, which was about thirteen screens of scrolling, so it has a contents list and can open in a window of its own beside the game. The contents list is off until you ask for it, and the window remembers where you put it and how big you made it.",
	CHANGELOG_340_3 = "Every one of the eleven profession advice routes was wrong. Ten are now corrected against Blizzard's own game data. The worst: Enchanting was backwards in a way that cost you real points, because disenchanting reads raw Skill and ignores every crafting stat - the first fifty points we recommended did nothing for it. Inscription's order was not merely slow but impossible to follow. Blacksmithing lost a step we had added in July with a source that did not support it.",
	CHANGELOG_340_4 = "We were telling people to spend Knowledge Points they could not spend. If no specialization can be unlocked yet, the line now says so and tells you to raise the skill first, instead of \"spend it\".",
	CHANGELOG_340_5 = "Corrected: the work orders chapter said a crafter can take four public orders per day. You hold four and one comes back each day - about seven a week, not twenty-eight. It also described one order table, when there are two counters: you order at the table, and you craft for others at your own profession's workbench. Standing anywhere else there is no button and no list, which is the single most common mistake with that system, and our own chapter was causing it.",
	CHANGELOG_340_6 = "New: a button and /mh fp that point the arrow at the nearest flight master from wherever you are standing, in every zone. Silvermoon's two flight masters are also on the city guide now - the guide listed portals, Timeways and even Mythic+ teleports, and never the one thing you use most.",
	CHANGELOG_340_7 = "Also: the list under the advice line stopped calling itself \"your open choices\", because those are individual nodes inside your trees rather than alternatives to the advice above them - and it now says four of how many instead of quietly showing four.",
	CHANGELOG_340_8 = "Translations: everything new in this release is English in German, French, Spanish, Portuguese and Italian for now. Nothing is broken - untranslated text falls back to English. The Dutch and English packs are complete, and the rest follow within a few days.",
	CHANGELOG_330_1 ="The Knowledge Point chapter opened by telling you your points can never be refunded. Untrue since 11 August: you get one reset per profession, from Theremis in Silvermoon City, and it also takes back the recipes those points taught you. There is a route button to him now, and he turns up in the search. You still cannot waste points - only spend them in an awkward order.",
	CHANGELOG_330_2 = "Engineering was sending you to Recycling last. In Midnight, recycling is how you discover most recipes, and it stays switched off until points go in, so our route let you conclude the feature was broken. It is the first step now. Leatherworking also stopped contradicting itself: the route said armour tree first, the text beside it said the opposite.",
	CHANGELOG_330_3 = "Three gear slots could never reach a recommendation, because of how our table was built rather than because nothing exists. Rings were filed by secondary stat and so could never offer Eyes of the Eagle. Weapons the same, which hid the primary-stat enchant. Shoulders now carry the same Speed, Leech and Avoidance trio that head and feet already had. Every id was read from your own client.",
	CHANGELOG_330_4 = "Seventeen flask and combat-potion picks were still the set from May. They are refreshed against the guide we already cite, and there is now a checker that compares our picks to that guide, so this can go stale loudly instead of quietly.",
	CHANGELOG_330_5 = "Ritual tiers show item levels again, measured at the obelisk this time: 215, 231, 244, 259, 268 and 275. Tier 6 exists, wants six challenges, and we had been contradicting ourselves about how many tiers there even are. Also corrected or withdrawn: two Codex crest claims that outlived their season, the Field Accolade vendor tracks and their prices, a Spark of Radiance that belongs to the previous expansion, a weekly the reset routine still sent you to after it stopped being offered, and raid boss names, which now come from the journal instead of our own list.",
	CHANGELOG_330_6 = "Coming next: a much larger professions update - beginner chapters on quality, the six profession stats, Concentration, work orders and making gold, all written against this patch. Midnight Helper is a one-man project, which is why updates arrive in bursts rather than on a schedule. This one is mostly a correction pass: things we said that had quietly stopped being true.",

	CHANGELOG_320_1 = "Correction, measured on a live client: tiers 9, 10 and 11 hand out the same GEAR as tier 8, but not the same crests. A tier 8 run pays Champion Mistcrest and a tier 11 run pays Hero Mistcrest, so climbing past 8 does buy you something after all - just not out of the chest. The previous version said otherwise and was wrong.",
	CHANGELOG_320_2 = "The consumables check no longer tells you that you have no health potion when you do. Season 2 replaced it with Concentrated Silvermoon Health Potion, and brewing that one consumes 25 of the old, so everyone who upgraded was being marked as missing it at every dungeon door.",
	CHANGELOG_320_3 = "Both ends of the Coiled Isle portal are now findable. The way in is a pin in the City Guide's Travel section, on a coordinate measured standing at Astalor rather than taken from a guide - the old one was four points out. The way back has a waypoint in the Prey guide, which is the half nobody writes down.",
	CHANGELOG_320_4 = "New button on the Enchants tab opens the socket window for the slot with the empty socket. It appears only when you actually have one. Midnight Helper told you which gem to use and never how to put it in.",
	CHANGELOG_320_5 = "Rares that need explaining now say so out loud, in chat, when you get close: Coin-Eye Skully swims and has no fixed spot, and Farthik only appears after you open the chest. The note used to sit on our own arrow, which is invisible to everyone running TomTom.",
	CHANGELOG_320_6 = "Smaller fixes: the consumables board no longer opens itself in a raid, where it could only ever show five of forty; travel advice no longer names an arbitrary flight point or calls a delve 'another continent'; The Ring of Glory warns that the higher tiers send three loose golems and that Gnok gets up again; and the About window now credits the addons and guides we check our facts against.",
	CHANGELOG_310_1 = "Venomfall Deeps has a coach page. It was the one delve with nothing at all, and now it opens with a red warning: Azta'rec's Wrath of Ula'tek kills you from full health, your own death recap marks it avoidable, and it fires during the quadrant intermission. His abilities also repeat in a fixed order, so you always know which one is the interrupt.",
	CHANGELOG_310_2 = "Delve rewards are back, and every number was read off the entrance window rather than copied from anywhere: end chest and Trovehunter's Bounty for all eleven tiers, with the upgrade track beside each. The useful part is what it shows - tiers 9, 10 and 11 hand out exactly what tier 8 does, so climbing past 8 for loot buys you nothing.",
	CHANGELOG_310_3 = "The Great Vault column fills itself in as you play. Run a delve and your own vault reports what that tier is worth this week, marked with a star so it is never mistaken for a published table. No guide, no datamine - your character's week.",
	CHANGELOG_310_4 = "Fixed, and it went out in 3.0.0: German, Spanish, French and Portuguese were showing raw escape characters on screen - 362 places where a paragraph break printed as the letters backslash-n, and 116 where every quotation mark carried a visible backslash. Almost all of it in the Role Academy. Spanish also showed an unfinished translation marker where a number belonged.",
	CHANGELOG_310_5 = "German gained the whole DPS Academy track, five missing heal chapters and 49 dungeon boss tips. Those tabs used to show German and English side by side in the same window.",
	CHANGELOG_310_6 = "Also: the Codex button that said \"Void & Rituals\" is now \"World content\", because Prey hunts, rares, Showdowns and Turbulent Timeways were all filed behind a name that hid them. Sixteen more hazards. The Coiled Isle portal is explained in the Codex with a waypoint to where that questline starts. And several messages that used to mislead: \"update the addon\" now says which text is missing, a delve that hides your coordinates says so instead of asking you to try again, and sharing tips no longer refuses because one section of three is empty.",
	CHANGELOG_300_1 ="New: /mh plan gives you the whole way to your target as steps you can click - the door rather than the flight master when the door is closer, and the inner Amani hop only when it actually saves you walking. All three Windcaller landing spots were measured in game, so the choice is arithmetic now instead of a guess.",
	CHANGELOG_300_2 = "The route arrow follows that plan. It steers to the first step that is on your own map, replans as you move, and says \"you are here, walk through\" instead of spinning when you are already standing on a step. It no longer reads an unreadable map as \"another continent\".",
	CHANGELOG_300_3 = "The Coiled Isle is finished: the Mysterious Mix Master's ten offerings with their three ingredients each, both new hunts, and one Route button in the card header instead of ten identical ones all pointing at the same cauldron.",
	CHANGELOG_300_4 = "Fixed: every Coiled Isle treasure was invisible to the search box. The index read a field those hunts deliberately leave empty, so searching for a treasure you own found nothing. It now reads the name your own client gives it, which means it works in your language too.",
	CHANGELOG_300_5 = "The command list was missing nine features that shipped months ago, and the list itself could not be found by searching for \"commands\". Both fixed, and the measurement commands now sit in a group of their own so they are recognisable as such.",
	CHANGELOG_300_6 = "The Ring of Glory opens with a red warning: the golem's slam cannot be interrupted and lands underneath you, so stun it or take it on a defensive. It says so up front because patch 12.1 no longer lets an addon see which spell an enemy is casting - a live warning is not possible, and pretending otherwise would be worse than saying it plainly.",
	CHANGELOG_2180_1 ="New: the Delve Coach lists what will hurt you where you are standing - 173 hazard names across 20 instances, from every Midnight dungeon and delve to the lair and the raid. It goes by where you actually are, never by whichever page you have open, because the coach is also something you read while sitting in a city.",
	CHANGELOG_2180_2 = "Season 2 now opens when YOUR region's weekly reset says so, not on one fixed date. The old gate would have unlocked Season 2 content a day early for everyone in Europe. The lair tip named that same day, and now names both.",
	CHANGELOG_2180_3 = "Two achievement hunts join the list: Soft Underbelly and Oppose the Foes. They were held back because several targets had no coordinates - which turned out to be right, since those only appear while an event is running. They are checklists now, and the arrow skips whatever has no place to go.",
	CHANGELOG_2180_4 = "New: /mh keys explains the four Altar of Corrosion nodes you cannot simply buy - which item unlocks each one, where the thing it opens sits, and what the two powers do. Where two sources disagree, it says so instead of quietly picking one.",
	CHANGELOG_2180_5 = "Fixed: the dispel icon had never once appeared, and the flight banner had never named where it was taking you. Both were the same one-line mistake in different files, invisible from outside. A build check now watches for it.",
	CHANGELOG_2180_6 = "/mh keys and the hazard lists read in all seven languages, and every spell and criterion name comes from your own game rather than from anything typed here - so they are already correct in your language and cannot drift from the patch.",

	CHANGELOG_2170_1 ="New: /mh curios explains Valeera's delve curios. Every line is read from your own game at the moment you ask, so it describes the ranks you actually have. It deliberately does not rank them for you - which option is best depends on your spec and your delve, and nobody measured that.",
	CHANGELOG_2170_2 = "Seven Coiled Isle treasures cannot simply be walked to. The achievement route now names the step that unlocks each one and puts its coordinates on a button you can click, instead of leaving you at a chest that will not open.",
	CHANGELOG_2170_3 = "The flight map now highlights the stop you need. It used to only name it in text, which meant reading a sentence and then hunting the same name across a map full of pins.",
	CHANGELOG_2170_4 = "New: /mh mount <text> searches the mount journal the way /mh ach searches achievements, and reports what your own client knows rather than what a guide claims.",
	CHANGELOG_2170_5 = "A shortcut to The Coiled Isle: the portal in Silvermoon City, and the one back, appear in route guidance once you have finished the quest that creates it. Until then they stay hidden - a portal you are told about but cannot use is worse than no portal at all.",
	CHANGELOG_2170_6 = "Fixed: buttons whose labels ran past the edge of the frame in the longer languages, criteria that showed a question mark instead of a name, a crash when a route hit one of those, and an error at a delve boss caused by a value the game now keeps secret.",
	CHANGELOG_2160_1 ="Delves have a chest route. The coach has a Chests button that sends the arrow to the nearest Sturdy Chest you have not opened and moves on by itself once you do - 36 chests across 13 delve maps. Blizzard's own pin cannot be placed inside a delve, so this uses the addon's arrow, which can.",
	CHANGELOG_2160_2 = "It says when it is unsure. Whether a chest counts as done is read from a quest flag, and where that flag cannot be read the chest stays in the route rather than quietly disappearing - so the cost is a chest you walk to twice, never one the route hides from you.",
	CHANGELOG_2160_3 = "Travel help got real. Point at something on another map and the arrow now goes to the flight master you can walk to first, then hands over to the destination the moment you board. The flight map itself tells you which stop to click, and says so when that stop is not on your map yet.",
	CHANGELOG_2160_4 = "Flight points went from 23 to 649 across 154 maps, and they respect your faction, so the advice works outside the Midnight zones too.",
	CHANGELOG_2160_5 = "New: /mh binds. It reads the keys you actually have - including anything you changed by hand - and shows them in a window you can copy and print. It names the Assisted Combat slot for what it is rather than for the spell it happens to be suggesting, and marks keys that duplicate another.",
	CHANGELOG_2160_6 = "Fixed: the Layout tab's right-hand column showed spells with no key beside them. The keys were there and being drawn off the edge of the panel, which looked exactly like an ability with no bind.",
	CHANGELOG_2150_1 ="The two 12.1 delves are real now: Gnarldor Isle and The Ring of Glory sit in the Delves panel, the coach and the picker - found on your own client, not copied from a datamine. Each has a route with its three Sturdy Chests as clickable waypoints, its bosses with the two or three things a first-timer must know, and 3D models.",
	CHANGELOG_2150_2 = "The Venomous Abyss raid coach is filled in: beginner steps for all eight bosses with clickable spell links, tank and healer notes where the data was solid, and a strip of 3D boss models measured from the game's own journal. A note above it says the tips were written before the raid opened - they get verified against the real fights after 18 Aug.",
	CHANGELOG_2150_3 = "The Codex got a Coiled Isle shelf. The Vaults of Atal'Utek wall of text is now three readable articles - the zone, the Altar's four keys, and The Honored Dead - and every coordinate in them is a clickable waypoint link. The Honored Dead article has a Follow the route button that starts the same twelve-stop route the Achievements tab runs.",
	CHANGELOG_2150_4 = "Coordinate links use the addon's own arrow system: TomTom if you have it, otherwise a Blizzard pin with SuperTrack, plus travel advice for getting to the zone first.",
	CHANGELOG_2150_5 = "A crest bundle you cannot open now says why before you click it: the tooltip shows the season total (for example 100/100) and explains that spending does not help - the cap counts what you have earned and rises at the weekly reset. Fully blocked bundles drop out of the Openables button instead of sitting in the way.",
	CHANGELOG_2150_6 = "The Openables list also reads the game's own has-loot flag now, so containers our patterns missed show up on their own.",
	CHANGELOG_2150_7 = "The Codex no longer calls itself a Season 1 handbook, and the vault tooltip note about Season 1 item levels stands until Season 2 numbers are measured. The delve picker fits thirteen delves.",
	CHANGELOG_2150_8 = "Er'inye's key items are explained in the Codex: showing him a key is a hint about where it belongs, not an unlock - and where the keys drop is honestly marked as unsettled.",
	CHANGELOG_2140_1 = "New: /mh setup. Laying out your bars was a set of commands you had to run from memory, in the right order, on the right character - and getting that wrong cost one of us eight keybinds. It is a panel now. It says who you are and whether your keys are account-wide or this character's own BEFORE offering anything that changes them, and nothing destructive happens on a single click.",
	CHANGELOG_2140_2 = "New: the addon offers, once. Open Midnight Helper on a character whose bars have never been set up and a card asks whether it should do it for you. There was no way to discover /mh setup existed - a changelog is read by nobody and the store page is read once, before installing. Dismiss it and it stays dismissed.",
	CHANGELOG_2140_3 = "New: our bar layout as something you can apply, not a picture to copy by hand. It changes action bars 1-8 and nothing else, so your minimap, unit frames and macro bars stay put, and a button next to it puts your old layout back. It refuses politely if another addon is already arranging those bars.",
	CHANGELOG_2140_4 = "New: thumb-button keys onto action bar 8. If your mouse sends 6 7 8 9 0 - instead of mouse buttons, one press puts them on bar 8 and leaves every key you already bound exactly where your hands expect it. A layout change is a habit change, so it shows you the plan first and moves nothing until you press again.",
	CHANGELOG_2140_5 = "New: a small quick bar, off by default: /mh bar. Midnight Helper, reload, the setup panel, and leaving a group - including leaving a delve, which needed its own call because solo in a delve there is no party to leave.",
	CHANGELOG_2140_6 = "New: your healing potion and healthstone as keybinds instead of action bar slots. Bind them in Blizzard's own keybinding screen under Midnight Helper. Nothing is bound by default.",
	CHANGELOG_2140_7 = "New: /mh fps reads out the graphics settings that cost the most frames and changes none of them. It tells an untouched default apart from a deliberate choice, because the two look identical and only one is worth mentioning. Also new: a Details! damage meter page, which copies a profile for you to paste - it never imports anything on its own.",
	CHANGELOG_2140_8 = "Ready for patch 12.1. The world boss scan used a function 12.1 removed and failed silently, falling back to a stale answer. In combat, 12.1 hides some of your own buffs and reports them as simply not there - measured, three of five - so the addon now answers “cannot tell” instead of “you do not have it”. And the Season 2 gate opened on patch day because it keyed off a number that changes with the patch rather than the season.",
	CHANGELOG_2140_9 = "Fixed: the search box did not index the Addons pages at all, so searching for the tools they cover found nothing. Commands are searchable by what they do rather than what they are called. Shift+scroll now resizes every dialog, not just one. And the About window credited the wrong people.",
	CHANGELOG_2130_1 = "New: every command, in the addon. The Tools page now lists all forty of them in groups, with a line each saying what they do. Most of this addon was reachable only by typing something you had to know already; the linter now fails the build if a listed command is not routed, so the page cannot drift from reality.",
	CHANGELOG_2130_2 = "Now announced: the action prompt. A large icon appears when your interrupt applies to what your target is casting, and when your target carries something you can purge. It has been in the addon unannounced since it could not be confirmed working; it has now been watched doing its job. Off by default: /mh prompt, then drag it where you want it.",
	CHANGELOG_2130_3 = "New: the purge prompt can speak. /mh prompt sound cycles between spoken, a chime, and silence. Interrupts stay silent on purpose - the game lets an addon show whether a cast can be kicked but never read it, and playing a sound means reading it.",
	CHANGELOG_2130_4 = "Fixed: the purge prompt printed the word Purge over everyone's icon - the shaman's name for it - so a mage went looking for a button they do not have instead of Spellsteal. It names the actual spell now. It also lit up on friendly players, who always carry something dispellable, so pressing it answered Invalid target; enemies only now. Shaman and Hunter were missing entirely - four classes instead of two.",
	CHANGELOG_2130_5 = "Fixed: four places read a unit GUID with a check that cannot tell a secret value from a normal one, two of them in the raid and delve coaches. On a boss whose GUID the client hides, that throws an error mid-fight.",
	CHANGELOG_2130_6 = "Ready for patch 12.1: the Coiled Isle arrives with nine rares, their coordinates and their kill quests measured rather than guessed, and Altar of Fangs arrives with beginner steps for all three bosses. Both stay hidden until your client is actually on 12.1, so nothing appears before it exists.",
	CHANGELOG_2130_7 = "New: /mh goto 47.0 62.2 points the arrow at any spot in the zone you are in, naming it if we know what stands there. Removed: /mh kicks who, which could never work - Midnight refuses combat log access to every addon, this one included.",
	CHANGELOG_2120_1 = "New: Party targets. A small panel showing what every group member is attacking, with their role, their class colour and the raid marker on their target. Click a line to take that target yourself — it works in combat. Drag it anywhere, drag the corner to widen it. Off by default: switch it on with /mh partytargets or in Settings.",
	CHANGELOG_2120_2 = "Fixed: the route arrow stayed hidden for anyone who also had WaypointUI installed. It was deliberate — one guide on screen — but it quietly cancelled a feature this addon advertises, and a pin and an arrow answer different questions. The arrow now draws alongside it; /mh arrow yield restores the old behaviour.",
	CHANGELOG_2120_3 = "Fixed: the route arrow could barely be seen against dark ground. Its halo was black, which only helps on bright backgrounds. There is now a pale glow outside the dark edge, so it reads on both.",
	CHANGELOG_2120_4 = "New: Stay alive. At the top of the Role Academy's DPS track, your own buttons in the order a fight needs them — the shield you keep up, the one you press when your health drops, how you get away, how you interrupt. Built from your actual talents, so a replaced spell shows the name on your bars.",
	CHANGELOG_2120_5 = "Fixed: the first-run popup promised the addon opens with Alt+M. That key is only assigned when it happens to be free, so for some players the very first thing the addon said was untrue. It now points at /mh and offers the keybind as something you set yourself.",
	CHANGELOG_2111_1 ="Fixed: the crest pages claimed a weekly cap of roughly 100 per colour. There is no such cap — the game reports none on any tier — and the claim was already removed from the English and Dutch guide text on 22 July. It was still there in the Codex in all seven languages, and in the crest guide in German, French, Spanish, Portuguese and Italian. Gone everywhere now.",
	CHANGELOG_2110_1 = "New: the Season 1 checklist now tracks what actually disappears with the season - Delver's Journey, the “of the Dawn” achievements, the Nullaeus nemesis kills and the Prey capstone. Each one ticks itself off; none of them are guesses.",
	CHANGELOG_2110_2 = "New: a Codex article on what a season rollover really does to your gear, your currencies and your progress tracks - written so it stays true next season too.",
	CHANGELOG_2110_3 = "New: milestones now arrive on their own card instead of a grey chat line, and stay long enough to read. /mh milestones preview shows you what one looks like.",
	CHANGELOG_2110_4 = "Changed: the big 3D boss model in the boss window is off by default. If you turned it on yourself, it stays on.",
	CHANGELOG_2110_5 = "Changed: searching the Codex now matches what an article is about, not just its title - so “reset” finds the season article.",
	CHANGELOG_2110_6 = "Fixed: patch 12.1 no longer throws errors during delve fights. The combat warning's glow border was doing arithmetic the new client refuses to allow.",
	CHANGELOG_2110_7 = "Fixed: the death recap stopped reporting the same refusal every single session, an accessibility alert could be hidden behind a toast, and the Delver's Journey kept nagging about a track you had already finished.",
	CHANGELOG_2100_1 = "New: your professions now tell you where your Knowledge Points should go. Once the recommended trees are filled, the advice names the exact node to spend on, and every open choice is listed below it with what it does - read live from the game, so it works for all eleven professions and in your own language.",
	CHANGELOG_2100_2 = "New: that profession advice shows on This Week and in a panel beside the Blizzard profession window, so it is there the moment you open your trade skill. The advised build order was checked against the current guides for every profession.",
	CHANGELOG_2100_3 = "New: the Professions course now opens each chapter with a plain-language intro, and tells you where to actually click to spend points (the Specializations tab). You can also reach it by searching 'academy'.",
	CHANGELOG_2100_4 = "New: milestones quietly mark your genuine firsts, a Codex tip of the day appears on This Week, and season counters start tracking for a future look-back.",
	CHANGELOG_2100_5 = "Fixed: the route arrow now returns to your route after you detour to a rare - whether you kill it, someone else does, or it is already gone when you arrive. It stays put on a rare that is still alive.",
	CHANGELOG_2100_6 = "Fixed: the crest panel counted a hundred Veteran crests you did not have, the weekly essence line no longer poses as progress it cannot see, a weekly cap that does not exist was removed, and three profession buttons that did nothing were taken out.",
	CHANGELOG_290_1 = "New: Midnight Helper now puts a small panel beside the Blizzard windows you already use. Your character sheet shows missing enchants, empty sockets, your tier set and which slots have hit their upgrade ceiling. The Mythic+ window shows your Great Vault dungeon row. The Adventure Guide shows the boss tips for whichever boss you selected, and the mount collection shows your wishlist.",
	CHANGELOG_290_2 = "The panels sit beside the window, follow it when you move it, and can be dragged wherever you want them - they remember where you put them. /mh panelreset puts them all back.",
	CHANGELOG_290_3 = "New: /mh tracks answers the question that stops most people - I am on Hero 6/6, now what? It lists which slots are at their upgrade ceiling and names the two ways onward: the Great Vault, and crafting. It also says the part that is easy to miss - the top crests are earnable solo, through high Bountiful Delves and repeatable Tier 6 Ritual Sites, so you do not need a raid group.",
	CHANGELOG_290_4 = "New Codex entry, Getting gear crafted: sparks, crests, missives and how to place a crafting order - including the trap that sinks most first attempts, which is that the crafter cannot supply your sparks and crests.",
	CHANGELOG_290_5 = "New: every one of the 43 bosses with tips now has a damage-dealer note as well. Only tank and healer notes existed before, so damage specs - most players - saw nothing.",
	CHANGELOG_290_7 = "Fixed: your weekly list now recognises what you actually picked up. Lady Liadrin offers four quests from a pool of twelve and Midnight Helper only knew four of them, so most weeks it kept telling you to go and fetch a quest already in your log. The Showdown weekly from Riftblade Maella was never listed at all, and now is.",
	CHANGELOG_290_6 = "Fixed: the Mythic+ vault breakdown called your runs keys and could print nonsense like Slot 1: 5/1 done. The dungeon vault row counts heroic and timewalking runs too, and now says so.",
	CHANGELOG_284_1 = "Fixed: the Omnium Folio button now works everywhere. It could open a Covenant Sanctum instead of the rune window, because visiting an old-expansion zone leaves the minimap button stuck on that page. Pressing the button now puts it back on Midnight first. It also identified the rune page by its English name, which broke it on every other language.",
	CHANGELOG_284_2 = "Fixed: the profession panel was showing wrong currency balances and comparing them against recipe costs. Every Artisan's Moxie and Unalloyed Abundance id turned out to belong to something else - one was a hidden internal counter. All of them are gone: the line now disappears rather than quoting a figure we cannot stand behind.",
	CHANGELOG_284_3 = "Fixed: a crash when opening the profession panel, and a burst of 'tried to call the protected function' errors from the death recap in dungeons.",
	CHANGELOG_284_4 = "New: the dispel reference now covers tanks and DPS, not just healers - it lists what your own spec can actually dispel. The Role Academy also finally has DPS content, which was missing altogether and was hiding a crash.",
	CHANGELOG_284_5 = "New: a copy button for sharing ritual routes. Ritual Sites now read as tiers 1-6, Season 2 content appears when the season opens rather than when the patch lands, and the heal-lens, dispel reference, consumable board and Mythic+ commands are translated into German, French, Spanish, Portuguese and Italian.",
	CHANGELOG_283_1 = "Fixed: the Omnium Folio button could open a Covenant Sanctum instead of the rune window. It was reading the landing page frame to decide, which reports Midnight even while the minimap button is parked on an old expansion. It now asks the button itself what it will actually open.",
	CHANGELOG_283_2 = "Ritual Sites now correctly read as tiers 1-6 (Tier 6 had been live for a while).",
	CHANGELOG_283_3 = "The heal-lens, dispel toolkit, consumable board and Mythic+ commands are now translated into German, French, Spanish, Portuguese and Italian instead of falling back to English.",
	CHANGELOG_282_1 = "Fixed: the profession panel was showing the wrong currency balances. Artisan's Moxie and Unalloyed Abundance were reading currencies belonging to something else entirely - one of them a hidden internal tracker - and comparing those numbers against recipe costs. Every id that could not be verified in-game has been removed, so the line now disappears instead of quoting a number we cannot stand behind.",
	CHANGELOG_282_2 = "Fixed: a crash when opening the profession panel, and a burst of 'tried to call the protected function' errors coming from the death recap in dungeons.",
	CHANGELOG_282_3 = "New: the dispel reference now covers tanks and DPS too. Your toolkit lists what your own spec can actually dispel, instead of only healers seeing it.",
	CHANGELOG_282_4 = "New: the Role Academy finally has DPS content. It was missing altogether, and its absence was hiding a crash.",
	CHANGELOG_282_5 = "New: healer boss tips on more bosses, in Magisters' Terrace and The Blinding Vale - including when to purge a buff off the boss rather than cleanse a player, and when someone simply needs healing back to full.",
	CHANGELOG_282_6 = "Fixed: the Omnium Folio 'Open rune window' button on non-English clients. It recognised the rune page by its English name, so every other language was wrongly told the button was on another expansion. It also no longer reports success when no window actually opened.",
	CHANGELOG_282_7 = "New: a copy button for sharing ritual routes, and Season 2 content now appears at the right moment - the patch arriving is not the same thing as the season opening.",
	CHANGELOG_281_1 = "The boss guide now reaches you at the pull. It opens on the boss you are actually fighting, and when combat hides it a small button brings it straight back — so it is no longer a flash you never got to read. This matters most in follower dungeons, where an NPC tank pulls before you can.",
	CHANGELOG_281_2 = "New: a mount wishlist. Star any mount in the Mounts tab and 'This Week' reminds you which of your picks you are still chasing. The star is the gold favourite star, and clicking a reminder opens the Mounts tab.",
	CHANGELOG_281_3 = "New: /mh groupbuffs tells you which raid-wide class buffs your group is missing — and says plainly when the game hides party auras from addons instead of claiming everything is fine.",
	CHANGELOG_281_4 = "New: /mh pawn exports your spec's stat weights as a Pawn scale you can paste straight into Pawn. New Codex entry explains gear upgrade tracks: what 'Hero 3/6' means, why the track sets your ceiling, and where to upgrade.",
	CHANGELOG_281_5 = "Fixed: a phantom 'Trovehunter Bounty detected!' popup that appeared in dungeons where no bounty exists. Any toast without a title was falling back to that text. Also fixed: the addon icon and minimap button were never drawn at all, a crash when opening the window inside delves and follower dungeons, and a crash when exporting to Pawn.",
	CHANGELOG_281_6 = "New: a Discord invite in Settings and on 'This Week', for questions, ideas, or helping translate. The addon stays free either way.",
	CHANGELOG_280_1 ="New: a spec-aware toolkit for every role in the Role Academy. Healers get their healing cooldowns labelled with what each one is FOR (a raid-wide hit? the tank? sustained damage?), a deepened beginner course, and a 'what can I dispel?' reference. Tanks get their active mitigation and personal defensives. DPS get their damage cooldowns and personal defensives — a dead DPS does zero. Hover any spell for its tooltip; the list only shows what you actually have.",
	CHANGELOG_280_2 = "New: 'what just killed me?'. In dungeons and raids Midnight Helper names the blow that killed you plus a short lesson. In delves, ritual sites and follower dungeons the game hides the cause from addons entirely — so there it opens Blizzard's own Death Recap for you instead, which does still work. It asks once whether you want that, and you can change it any time in Settings.",
	CHANGELOG_280_3 = "New: a tank pull summary. After a real pull, one line on how it went — your active-mitigation uptime, which defensive cooldowns you used, and a gentle nudge if you used none (Brewmaster gets a Stagger reading). Trivial trash is skipped, and where the game hides your buffs it says so instead of claiming a false 0%. /mh pullsummary, with boss / popup / status.",
	CHANGELOG_280_4 = "New: an interrupt scorecard — how your kicks actually went, landed versus wasted, with an optional private nudge when you fire one with nothing to interrupt. /mh kicks.",
	CHANGELOG_280_5 = "Mythic+: /mh mplus now shows your season best per dungeon and where another key adds the most rating, plus an honest gear pointer to the keystone tooltip and the Great Vault instead of numbers we cannot verify.",
	CHANGELOG_280_6 = "The keybind coach's interrupt card now also lists the other abilities that stop a cast — a stun, a silence — each tagged with why, while they keep their own key. Druids: your four forms now sit on the same keys in every spec (Travel on R, Cat/Bear/Moonkin on Shift+R/T/X).",
	CHANGELOG_280_7 = "Openables now recognises reward and currency packs ('Use: Collect 10 …') and cosmetic appearances you have not collected yet, and hides items with a requirement you do not meet.",
	CHANGELOG_280_8 = "Season 2 is already in — the raid, lair, dungeon and the whole Mythic+ rotation — and stays completely hidden until patch 12.1 goes live, then lights up on its own. Nothing changes for you today.",
	CHANGELOG_280_9 = "Fixed: the main window now grows tall enough for the full sidebar (the last tab hung off the bottom); Codex entries no longer overlap the next title; the Omnium Folio button explains itself instead of opening another expansion's window; no more error spam in delves and ritual sites; and the death card no longer appears on PvP deaths.",
	CHANGELOG_270_1 = "New: loot upgrade tips. Hover any piece of gear and Midnight Helper tells you at a glance whether it's an Upgrade, Sidegrade or Lower for your spec, with the exact item-level change — using the same stat weights as the Great Vault advisor. Upgrades also get a small green arrow right on the bag item. Toggle with /mh loot.",
	CHANGELOG_270_2 = "New: a Season transition checklist. As a new season approaches, This Week shows what to wrap up in the current season and, once the patch is live, how to get ready for the next one. It reads the game itself, so it only appears when it is genuinely relevant — never a made-up 'done'. Open it with /mh season.",
	CHANGELOG_270_3 = "New: a post-run scorecard. Finish a Midnight delve or ritual and you get one friendly line — your time (with a nudge when you beat your own average or set a record) and your deaths. Toggle with /mh scorecard, or add /mh scorecard detail for the exact numbers.",
	CHANGELOG_270_4 = "The on-screen route arrow now guides you to delves, world bosses, the Trading Post, Silvermoon City and more — not just rares and treasures — even without TomTom installed. It is brighter with a dark outline so it stands out on any background, and 'find nearest bountiful delve' now really picks the closest one.",
	CHANGELOG_270_5 = "New in the Codex: a calm 'what a new season means' explainer, and a Season 2 glossary — crest, upgrade track, tier set, Catalyst, Bountiful, Nemesis, Lair and the start-of-season rescale — so the next season won't feel like chaos.",
	CHANGELOG_270_6 = "Fixed: an error that could repeatedly pop up inside delves, dungeons and Mythic+ (the game now hides some aura details in that content, which one of our alerts tripped over). Midnight Helper handles it quietly again.",
	CHANGELOG_270_7 = "Lighter at login: Midnight Helper now builds only your active language pack instead of all seven, using noticeably less memory when you log in.",

	CHANGELOG_260_1 = "New tab: Collectible mounts. A checklist of the 17 new Midnight mounts — a green tick for the ones you own, a red cross for the rest — each with your live progress, how to get it, and a floating 3D preview when you hover its name. Hover a Voidlight Marl line to see your balance across every character.",
	CHANGELOG_260_2 = "New page: Raids, in the Codex. Boss steps for all three Season 1 raids and their nine bosses, with tank/healer/dps lines and clickable spell links. The Raid Coach still opens by itself when a boss pull starts — this page is for preparing beforehand.",
	CHANGELOG_260_3 = "Home now leads with 'Next up': the single most useful thing to do right now, with a 'Take me there' button and a count of how many weekly things you have done. While you are levelling it never points you at endgame content you cannot do yet.",
	CHANGELOG_260_4 = "Search finds bosses: type a boss name to jump straight to its coach steps (52 bosses, dungeons and raids). It also finally finds the Collectible mounts, Raids and Pop-out windows tabs — those three were missing from the search index entirely.",
	CHANGELOG_260_5 = "A calmer window for newcomers: the welcome popup opens the Start Here roadmap instead of a tour of the buttons, Start Here leads with its six-step plan, and Home opens with fewer sections unfolded. Everything stays one click away and your choice is remembered; existing folded/unfolded choices are reset once so the new defaults apply.",
	CHANGELOG_260_6 = "Clearer navigation: the Character sidebar is grouped into Collections, Gear, Resources and Alts & history, and a few tabs got plainer names — Home is now This Week, SMC City Guide is Silvermoon City, and Launchpad is Pop-out windows.",
	CHANGELOG_260_7 = "Consistent colours everywhere: 'done' is the same green and 'do this' the same amber on every page. All of the above is translated into German, French, Spanish, Portuguese and Italian.",
	CHANGELOG_250_1 = "New Demon Hunter specialization supported: Devourer, the new Void spec. The keybind coach now maps its rotation, cooldowns and Void Metamorphosis onto your layout, and the consumables bar recommends the right flask and potion for it — just like every other spec.",
	CHANGELOG_250_2 = "Consumables updated for patch 12.0.7: flasks, potions, weapon oils, augment rune and feasts double-checked against the current guides.",
	CHANGELOG_250_3 = "New setting: hide the minimap button for a clean minimap — Midnight Helper is also reachable from the game's AddOns compartment (top of the minimap). You can open the window any time with Alt+M.",
	CHANGELOG_250_4 = "The Midnight 80-90 leveling tips page is now fully translated into German, French, Spanish, Portuguese and Italian.",
	CHANGELOG_250_5 = "Fixes: opening Settings while in combat (e.g. inside a Delve) no longer throws an error; a Delve crash tied to patch 12.x \"secret\" values is gone; a keyboard-layout tooltip crash is fixed; and toggling the Leveling/beta tabs now updates the window live without a reload.",
	CHANGELOG_250_6 = "New Guided mode for professions: a take-you-by-the-hand wizard that walks you through learning and levelling any of the 11 professions one step at a time, ticking steps off automatically as your skill grows, with trainer and Work Order waypoints. Open it from the Professions 101 (Course) tab.",
	CHANGELOG_250_7 = "More fixes: the Delve boss-coach prompt now offers at the boss room instead of on trash; the Delve consumables popup and the group Consumable Check no longer re-appear after the last boss or pop up solo in the open world; and the Ritual Site buttons always place a waypoint now.",
	CHANGELOG_241_1 = "Settings moved into the game's own Settings window (Game Menu > Options > AddOns > Midnight Helper): searchable, with a tooltip on every option and your language right at the top. The in-addon Settings tab is now a quick launcher with the Test/Preview buttons, and per-achievement visibility has its own subsection.",
	CHANGELOG_241_2 = "Fixed: the Missing Buff reminder is back in the open world. It was wrongly hidden across all Midnight zones because your health reads as a \"secret\" value there; it now trusts the game's own aura flag, while still staying quiet in delves and rituals where auras really are hidden.",
	CHANGELOG_241_3 = "Achievements: the four zone metas (Forever Song, Making an Amani Out of You, and the rest) now expand to show their sub-achievements with live progress.",
	CHANGELOG_241_4 = "Fixed: the delve \"open the coach?\" button no longer pops up when you target a quest giver or every random enemy — it now offers once per delve, on a hostile target only.",
	CHANGELOG_240_1 = "New Combat Safety warning: when an enemy casts a spell aimed at you, a movable red icon with a countdown appears so you can move or interrupt in time. Optional cast bars show several incoming casts at once, and an optional voice can speak the cast's name aloud. Turn it on/tune it in Settings under Notifications. Built to work with patch 12.x's new \"secret\" combat values.",
	CHANGELOG_240_2 = "Delve Coach: targeting an enemy in a delve now pops a small \"open the Delve Coach?\" button (out of combat), so you can pull up the boss tips without opening menus. It gets out of the way once you're fighting.",
	CHANGELOG_240_3 = "Fixes for patch 12.x \"secret value\" issues: no more Lua error when accepting a quest from a giver on the reset route, and the Missing Buff reminder no longer keeps telling you to re-apply a buff (e.g. a Shaman shield) in delves and rituals where auras are hidden.",
	CHANGELOG_231_1 = "Fix: the Missing Buff reminder could trigger a blocked-action error in combat — when a maintainable buff dropped or was reapplied mid-fight (for example on entering a ritual). Its click-to-cast button is now positioned independently of the reminder icon, so the icon is never treated as protected and can hide/show freely during combat.",
	CHANGELOG_230_1 = "The Leveling tab is completely rebuilt. A live keyboard layout reads your actual spellbook and lays out every ability by role — for all 13 classes and 39 specs — and keeps itself up to date as you level, swap talents/loadouts or change spec. Hand-tuned maps ship for a few specs; every other spec is built automatically from what you can currently cast, so there are no wrong or missing spell IDs.",
	CHANGELOG_230_2 = "New spell-strip cards under the keyboard group your abilities by purpose (builder, spender, AoE, interrupt, movement, defensives, dispel/CC, cooldowns, self-heals) with real in-game tooltips, and healers get a dedicated mouseover single-target heal card. A full-width 'Consumables & extras' bar shows flasks, food, runes and more with live ready/missing status.",
	CHANGELOG_230_3 = "New Missing Buff reminder (replaces the standalone MissingClassBuff addon): a movable on-screen icon appears when you can cast a maintainable class buff you don't have active — raid buff, form, shield, weapon imbue, poison, stance, pet or an ally buff. Click it to cast (out of combat); verified across all 13 classes.",
	CHANGELOG_230_4 = "New Openables tracker: a movable button with a count badge and list for openable bag items — caches, lockboxes, satchels, quest containers. Left-click opens the next one; it hides items you can't open yet at your level, and plays a sound when a new openable drops.",
	CHANGELOG_230_5 = "New Fast Mark bar: quickly mark your target (skull, cross, …), drop world markers on the ground (left-click set, right-click clear) and run a ready check. It appears only while you're in a party or raid. Enable it in Settings or with /mh mark.",
	CHANGELOG_230_6 = "The route arrow now shows a per-content icon and colour — rare (red), treasure (gold), achievement (yellow), reset route (blue) — so you can tell at a glance what it's guiding you to. If you have WaypointUI installed, Midnight Helper hands the route to its in-world pin instead.",
	CHANGELOG_230_7 = "The guide tabs are out of Beta, and everything new is fully translated into German, French, Spanish, Portuguese, Italian and Dutch. Plus fixes: ritual consumable checks now trigger on every ritual site, the treasure toast no longer vanishes when you move away, dungeon boss info opens when you target the boss, and route clearing is more reliable across all route types.",
	CHANGELOG_220_1 = "The route arrow now works WITHOUT TomTom. Midnight Helper draws its own on-screen direction arrow (with live distance) and drives the game's own map waypoint — keeping it on your next open treasure/rare/reset stop, advancing it the moment you arrive, and surviving flying between cities/zones — so routes guide you even with no TomTom (or HandyNotes) installed. Drag the arrow to reposition it, and resize it in Settings > General (or /mh arrowsize).",
	CHANGELOG_220_2 = "Safety net: if TomTom is installed but its big arrow drops out (for example an older TomTom whose map maths can't re-point across zones), Midnight Helper now falls back to the built-in waypoint so you're never left without direction. When TomTom's arrow is working, this stays fully out of the way.",
	CHANGELOG_220_3 = "The cross-zone arrow re-point no longer borrows another addon's HereBeDragons library — it uses the game's own map coordinates, so cross-map routing behaves the same for everyone.",
	CHANGELOG_220_4 = "The weekly/reset route (vault > quest givers > hub > trainers > station) now tours every stop once and moves on when you accept a quest there or stand on it briefly — so the arrow no longer sticks on stops it can't auto-verify (a rotating weekly, a ritual intro you skip, an empty trainer). Right-click the arrow, or use /mh clear, to wipe any active route.",
	CHANGELOG_211_1 = "Fixed: the route arrow no longer disappears — not when you arrive at a stop, not when you kill a rare on the way, and not when you cross between sub-zones (e.g. into Slayer's Rise while routing in Voidstorm). Midnight Helper now keeps the big arrow pinned to your next open treasure or rare itself, translating it onto whatever map you're standing on, so it flows even without TomTom's 'set closest waypoint' option.",
	CHANGELOG_211_2 = "New: skip the current route target with /mh skip (or a keybind under Esc > Key Bindings > Midnight Helper) — handy when a rare isn't up. The arrow moves to the next open one and you cycle back to skipped stops later.",
	CHANGELOG_211_3 = "Each achievement card now shows a coloured type tag (Treasure / Telescope / Lore / Rare), an 'Elite' flag on the tougher rares, and a hint on the ones that count toward Light Up the Night (Brilliant Petalwing mount).",
	CHANGELOG_211_4 = "The route how-to notes, step labels and chat/popup messages are now fully translated into all seven languages. Treasure/rare/item names stay in your game-client language to match the world.",
	CHANGELOG_211_5 = "Fixed: the 'you're nearly there' rare alert now only shows when you're actually heading to that rare, not when you pass a previously-routed one while routing a treasure.",
	CHANGELOG_211_6 = "New: the Achievements tab now breaks down Light Up the Night live — the four zone metas it needs (Forever Song, Making an Amani Out of You, That's Aln Folks!, Yelling into the Voidstorm), each with its own progress. Hover any of them for an accurate criteria checklist, and click the header to preview the Brilliant Petalwing mount.",
	CHANGELOG_211_7 = "Polish: zebra striping and a hover highlight on the checklist rows make it clear which Waypoint button belongs to which stop, and /mh arrowdebug adds an optional diagnostics log for routing support.",
	CHANGELOG_210_1 = "New Achievements tab: track Midnight's collectible achievements — Treasures, The Highest Peaks (telescopes), Midnight Lore Hunter and the zone rare hunters across all four zones — with live progress and one-click TomTom routing to whatever you still miss. The arrow auto-advances as you loot or kill.",
	CHANGELOG_210_2 = "Each achievement card shows the faction renown it earns (with your current renown level) and its completion collectible — pet, mount or toy — with a green check once you own it.",
	CHANGELOG_210_3 = "Expandable checklists: every treasure has a Waypoint button and a how-to tooltip on hover, plus a step-by-step hint toast for the tricky multi-step ones.",
	CHANGELOG_210_4 = "Top-of-tab summary: achievements done, collectibles owned, and your live progress on the 'Light Up the Night' meta toward the Brilliant Petalwing mount.",
	CHANGELOG_210_5 = "Route nearest open: one button sends the arrow to the closest treasure you still need, across every tracked achievement.",
	CHANGELOG_210_6 = "Tidy your list: open achievements sort to the top and completed ones to the bottom, and you can hide finished or unwanted ones (Settings > Tabs, or the 'all done — hide it?' prompt).",
	CHANGELOG_210_7 = "Shift-click a card to link the achievement in chat; Ctrl-click to open Blizzard's achievement panel.",
	CHANGELOG_200_1 = "Big redesign: the sidebar is now organised into four rooms — Me, Codex, Tools and Settings — so you find what you need faster.",
	CHANGELOG_200_2 = "New global search bar at the top: type a tab, tool or Codex topic and jump straight there. Pin your most-used tabs to the favourites row (+) for one-click access.",
	CHANGELOG_200_3 = "A breadcrumb in the title bar shows where you are, and tabs that have a Codex article get a 'Read in Codex' button.",
	CHANGELOG_200_4 = "New Tools Launchpad: open all the floating helper windows (Delve Coach, consumable board, boss window, curios, ritual boss) from one place.",
	CHANGELOG_200_5 = "Adjustable text size (A- / A+) for the content panels, so you can scale the guides to taste.",
	CHANGELOG_200_6 = "One settings home: every option now lives in the in-addon Settings tab, with Vault and Tabs as their own categories. Right-click the minimap icon or use /mh settings to open it — the old Blizzard panel and quick-settings popup are retired.",
	CHANGELOG_200_7 = "New gem advisor next to the enchant checker: it flags empty sockets and suggests the right gems for your spec.",
	CHANGELOG_200_8 = "The 'after the reset' route now auto-advances — the arrow moves to the next stop as you claim the Great Vault and pick up your weeklies.",
	CHANGELOG_200_9 = "Fully translated: the whole addon is now available in German, French, Spanish, Portuguese, Italian and Dutch (plus English), including a first-run onboarding tour for the new layout.",
	CHANGELOG_200_10 = "Fixes: the Info button now shows the actually-open tab; more rares get a 3D model preview; the profession trainer-weekly hint no longer mentions Enchanting on every profession; the treasure arrow survives crossing continents; and there's a new Warband Bank explainer in the Codex.",
	CHANGELOG_186_1 = "New: the group leader can pop everyone's consumable board with /mh boardall, so the whole party can re-check flasks, runes and food on demand.",
	CHANGELOG_186_2 = "New: a 'Final boss - open coach?' button reappears at a boss fight if you'd closed the Delve Coach earlier in that delve.",
	CHANGELOG_184_1 = "Consumable board redesigned: real item & spell icons with status, counts and buff timers. Click your own consumables — or your class buff — to use them straight from the board.",
	CHANGELOG_184_2 = "Raid & class buffs on the board: Arcane Intellect, Battle Shout, Power Word: Fortitude, Mark of the Wild and Skyfury. Hover a buff to see exactly who has it and who's missing (whole group, even cross-faction).",
	CHANGELOG_184_3 = "Smarter columns: the board only shows what's relevant — Healthstone only when a Warlock is present, weapon oil only for specs that use it, with no gaps.",
	CHANGELOG_184_4 = "The consumable check now also pops when you enter a ritual or delve (not just dungeons), and you can reopen the board with a middle-click on the minimap button.",
	CHANGELOG_184_5 = "Food (Well Fed) detection now covers every food, and hovering a slot you're missing shows the recommended item with a 'not in your bags' note.",
	CHANGELOG_184_6 = "Fixed: the Omnium Folio unlock counter now counts account-wide, so alts no longer show 0/5 when the rows are unlocked on your account.",
	CHANGELOG_184_7 = "Fixed: the delve/ritual death counter no longer resets after a /reload; a Lua error from 12.x 'secret' aura values; and the catalyst is now correctly the Matrix Catalyst, with how to unlock it.",
	CHANGELOG_183_1 = "Consumable ready-check: entering a dungeon checks your flask, augment rune, potions, food and healthstone — plus the group's buffs — with ready-check icons. /mh readycheck to run, /mh readytoggle or the new settings toggle to mute. Shows '?' instead of a false 'missing' when a slot can't be read.",
	CHANGELOG_183_2 = "Daggerspine Point now opens the floating boss window automatically at each boss (Mindbreaker, Selen'vjar), like the other dungeons.",
	CHANGELOG_183_3 = "New Codex article: the Ritual Sites Renown track — what each of the 8 ranks unlocks (orbs, treasures, decor, shrines, pets, the Void-Touched Hawkstrider) and why higher-rank sites give more.",
	CHANGELOG_183_4 = "Omnium Folio tab: a new 'Open rune window' button opens the Folio directly — handy if your UI hides the minimap expansion button (e.g. Ellesmere).",
	CHANGELOG_183_5 = "Folio weekly reminder now tells you what this week's Mote needs (e.g. collect Ritualized Arcana from Ritual Site elites).",
	CHANGELOG_183_6 = "Ritual Sites renown vendors Rae'ana (decor) and Sergeant Vornin (pets & mount) are now clickable waypoints in Silvermoon.",
	CHANGELOG_183_7 = "Fixed: the Omnium Folio unlock counter (and the Folio weekly reminder) now count account-wide unlocks, so alts no longer show 0/5 when the rows are already unlocked on your account.",
	CHANGELOG_183_8 = "Consumable ready board: a floating board appears on dungeon entry with each group member's ready-check icons. Drag it, SHIFT+scroll to zoom; it hides when you pull. /mh readyboard opens it manually.",
	CHANGELOG_183_9 = "Group bag sharing: groupmates running Midnight Helper share their bag status, so you see their flask/rune/potions/food/healthstone instead of 'bag unknown'.",
	CHANGELOG_183_10 = "Food check added, and your flask/rune now show green for the spec-recommended best, amber for an alternate.",
	CHANGELOG_182_1 = "Floating boss window: closing it with the X now only dismisses that one boss — the next boss brings a fresh window (a new pull, a ritual stage, or just targeting the boss). Permanent off via the new toggle below.",
	CHANGELOG_182_2 = "New 'Open automatically' toggle for the boss window (Dungeon Coach settings): turn it off to never auto-open it; it still opens on /mh bosswin.",
	CHANGELOG_182_5 = "Great Vault advisor: the tier-set note is now threshold-aware — it tells you whether a vault tier piece completes your 2- or 4-set bonus, or is just another piece with no new bonus yet (so a stat upgrade may win).",
	CHANGELOG_182_3 = "Fixed a Lua error in ritual scenarios on 12.x (boss unit IDs are now 'secret' values and could taint and error).",
	CHANGELOG_181_1 = "New Tier Sets tab: your class set, your 2- and 4-piece bonuses (hover for the live tooltip), and a live counter of how many tier pieces you have equipped.",
	CHANGELOG_181_2 = "New Currencies tab — where to earn and spend every Midnight currency, with live balances. Vendor names are now clickable to set a TomTom waypoint (across the addon).",
	CHANGELOG_181_3 = "Rare skull: route to a rare from the alert and a skull marks it on its nameplate as you arrive, so it's easy to spot.",
	CHANGELOG_181_4 = "Calmer, cleaner look: one unified gold, role icons instead of a colour rainbow on boss steps, softer links, and tooltips now appear at your cursor.",
	CHANGELOG_181_5 = "New 'Simple view' toggle at the top of the menu — hide everything but the core tabs (great for new players); set once, remembered on all your characters.",
	CHANGELOG_181_6 = "Plus the Val & Naigtal Showdown rares, an Enchants tab with one-click Auction House copy, and fixes (world-boss 'defeated' line across alts, enchant panel refresh, and more).",
	CHANGELOG_180_1 = "Raid & Mythic+ coaches: beginner boss steps for all the new raids (clickable casts), plus a Mythic+ tab with must-interrupts and a Beginner mode + glossary.",
	CHANGELOG_180_2 = "New Enchants tab: checks your gear for missing enchants and suggests one for your spec — click a suggestion to copy its name for the Auction House.",
	CHANGELOG_180_3 = "New Currencies tab: where to earn and spend every Midnight currency, with your live balances and a waypoint to each Renown Quartermaster.",
	CHANGELOG_180_4 = "New Events tab: every world event with live timers, click-to-route, and Shift-click 3D reward previews.",
	CHANGELOG_180_5 = "Opt-in Helper alerts, a Delve & Ritual log, and a fix so the world boss 'defeated this week' line is correct across your whole warband.",
	CHANGELOG_171_1 = "Floating boss window with a 3D model, and every boss step now reads natively in all six languages.",
	CHANGELOG_170_1 = "Dungeons tab: the Dungeon Coach (boss steps for all 12 dungeons) and a Dungeons 101 beginner course.",
	CHANGELOG_170_2 = "Rare alert supercharged: a draggable 3D-model toast, plus a weekly Coffer Shard cap alert.",
	CHANGELOG_170_3 = "The 'After the reset' routine now understands low-level characters.",
	CHANGELOG_160_1 = "'After the reset' routine on Home, with a one-click TomTom route along everything you still have open.",
	CHANGELOG_160_2 = "Per-slot Great Vault detail on every alt, and a Ritual Coach that shares tips in your groupmates' own language.",
	CHANGELOG_160_3 = "Weekly tracking for all 11 professions, and a Start Here first-week roadmap.",
	CHANGELOG_155_1 = "Keybinding fix: find it under Keybindings → Midnight Helper (not Other); default Alt+M; uses same path as /mh.",
	CHANGELOG_154_1 = "Keybinding: Esc → Keybindings → AddOns → Midnight Helper → Toggle main window (Stream Deck friendly — no macro bar slot needed).",
	CHANGELOG_153_1 = "World boss: weekly status resets correctly — last week's kill no longer shows as done on reset day.",
	CHANGELOG_153_2 = "World boss: fixed login Lua error (cache cleanup on startup).",
	CHANGELOG_153_3 = "Fix: no Lua errors in delves when nameplate addons show aura tooltips (delve story hook; from 1.5.2).",
	CHANGELOG_152_1 = "Fix: no more Lua errors in delves when nameplate addons (e.g. Platynator) show aura tooltips — delve story hook limited to map POI tooltips.",
	CHANGELOG_152_2 = "Delve story detection still works from world map / Area POI tooltips; secret tooltip IDs are skipped safely on 12.x.",
	CHANGELOG_151_1 = "Midnight Codex (beta tab): Season 1 handbook with live currency balances, Blizzard tooltips, and Open links to the right addon tabs.",
	CHANGELOG_151_2 = "Codex in the beta sidebar block — enable or hide in Esc → AddOns → Midnight Helper (per-tab + master switch).",
	CHANGELOG_151_3 = "Home: delve weekly trackers (Trovehunter's Bounty, Gilded Stash, Special Assignments) with account alt rollup.",
	CHANGELOG_151_4 = "Delve Coach: auto-selects the active boss in multi-boss delves; browse bosses in-session without breaking live detection.",
	CHANGELOG_151_5 = "Delve Coach: live delve boss 3D preview and story-variant detection fixes (map tooltip, Grudge Pit / arena fallbacks).",
	CHANGELOG_151_6 = "Fix: Trovehunter's Bounty no longer says \"use it!\" on Home unless the map is actually in your bags.",
	CHANGELOG_150_1 = "Home tab (opens by default): weekly reset countdown, account Great Vault status, world boss, weekly chores, and a shortcut to Rares.",
	CHANGELOG_150_2 = "Rares tab: per-character weekly tracking, nearest incomplete rare or a full route (true yard distances across maps).",
	CHANGELOG_150_3 = "TomTom route keeps the crazy arrow on the nearest waypoint instead of jumping to the last pin added.",
	CHANGELOG_150_4 = "Live rare alerts: sound + on-screen toast when a tracked rare is nearby (~500 yds), even with the main window closed.",
	CHANGELOG_150_5 = "Clicking the toast adds that rare as an extra waypoint without clearing a route you are already following.",
	CHANGELOG_150_6 = "Sidebar tabs grouped into sections; Reference renamed to Basics; minimum window height so tabs never overlap About.",
	CHANGELOG_140_1 = "Great Vault Advisor: ranks vault loot on Blizzard's Great Vault screen (ilvl, guide stats, tier sets). Auto / Raid / M+ profiles; optional Pawn.",
	CHANGELOG_140_2 = "Beta sidebar tabs: Guide, Leveling Guides, Macros, and Role Academy between Professions and Consumables—toggle in Esc → AddOns → Midnight Helper.",
	CHANGELOG_140_3 = "Vault reminders: chat summary, minimap ping, and login popup options in addon settings.",
	CHANGELOG_140_4 = "Six-language UI for advisor and beta settings (EN DE FR ES PT NL).",
	CHANGELOG_140_5 = "Fixes: beta tab settings checkboxes no longer cause Lua errors.",
	CHANGELOG_130_1 = "Delve Party Share: send delve tips to party, raid, or instance chat from Delve Coach (brief, boss, sections, copy). Test (/say) when solo.",
	CHANGELOG_130_2 = "Delve items popup: RAID-R Mini and Trovehunter's Bounty in delves—auto panel + minimap icons (in-delve only; left = popup, right = use).",
	CHANGELOG_130_3 = "Delve Coach: Shift + mouse wheel scales the whole panel (like Midnight Helper). Drag corner, bottom, or right edge to resize; wheel scrolls tips.",
	CHANGELOG_130_4 = "Boss spotlight: reliable first-load preview, loading text fix, and saved zoom per boss.",
	CHANGELOG_130_5 = "Fixes: party share only when you are really grouped; fewer chat errors; spell links in shared tips (EN/NL).",
	CHANGELOG_130_6 = "From here, small patch releases may use the Valeera codename in notes—major features stay on 1.x.",
	CHANGELOG_126_1 = "Delve Coach: floating tips for all 11 Midnight delves (Overview, Route, Trash, Boss) in English and Dutch.",
	CHANGELOG_126_2 = "Boss spotlight with 3D preview; scroll on the model to zoom in/out (saved per boss).",
	CHANGELOG_126_3 = "Blue spell links in tips; preview from Delves tab or /mh coach; auto-show in delve.",
	CHANGELOG_126_4 = "Draggable, resizable coach window with minimize.",
	CHANGELOG_126_5 = "Boss camera and tooltip fixes for retail.",
	CHANGELOG_125_1 = "New Role Academy tab: tank and heal tracks with prep checklists, triage tips, and a gentle ramp from delves to dungeons.",
	CHANGELOG_125_2 = "Quick links from Role Academy to Macros, Consumables, Leveling Guides, and Delves.",
	CHANGELOG_125_3 = "Search keywords (tank, heal, academy, mentor) open Role Academy.",
	CHANGELOG_124_1 = "Delve and profession routing: Blizzard map waypoint fallback when TomTom is not installed (SuperTrack + travel popup unchanged).",
	CHANGELOG_124_2 = "Account snapshot: profession weekly currencies in tooltip (Abundance, Dundun shards, Moxie summary).",
	CHANGELOG_124_3 = "Great Vault reset reminders: chat on login, minimap tooltip lines, and pulsing minimap icon (configurable).",
	CHANGELOG_124_4 = "Account snapshot polish: sort/filter, level/ilvl, stale badge, Untainted Mana-Crystals; consumables search routing.",
	CHANGELOG_123_1 = "Fixed Travel Assistant wrongly suggesting Hearthstone when you were already near a delve or inside one.",
	CHANGELOG_123_2 = "Fixed a Lua error when routing to bountiful delves (map position API).",
	CHANGELOG_123_3 = "Consumables sidebar tab: Wowhead-backed lists per spec, with guide search preview.",
	CHANGELOG_123_4 = "Clearer TomTom guidance (EN/NL): optional for map arrows; Travel Assistant works without TomTom.",


